########## packages/core/src/schema.ts
/**
 * The record contract. Imported by both the pipeline and the web app so that
 * anything rendered to a user is the same shape the pipeline validated.
 */

export type SourceClass =
  | 'regulatory' // SEC, IRS, other statutory filings
  | 'registry' // company registries, state SOS, Companies House
  | 'primary_web' // the firm's own site or its principals' own profiles
  | 'third_party' // press, conference programmes, job boards
  | 'vendor'; // paid/freemium data services - always named

export interface Evidence {
  sourceUrl: string;
  sourceClass: SourceClass;
  /** How the value was confirmed. Surfaced to the user verbatim, so write it in plain English. */
  method: string;
  observedAt: string;
  /** Named plainly whenever a commercial service touched this value. */
  vendor?: string;
}

export type CellStatus =
  | 'verified' // published on an authoritative source and checked
  | 'inferred' // derived (e.g. email pattern) and not independently confirmed
  | 'could_not_verify' // looked for it, could not establish it
  | 'rejected'; // our own validation found it invalid - must not ship

/**
 * No high-value value is ever a bare primitive. A cell carries its own basis,
 * which is what lets the UI show provenance without the pipeline and the app
 * having to agree on a side channel.
 */
export interface Cell<T> {
  value: T | null;
  status: CellStatus;
  evidence: Evidence[];
  /** 0-1. Drives the retrieval confidence gate, not just display. */
  confidence: number;
  /** Reason, when status is could_not_verify or rejected. */
  note?: string;
}

export type FirmType =
  | 'single_family_office'
  | 'multi_family_office'
  | 'advisory_or_wealth_manager'
  | 'unconfirmed';

/**
 * Firm type is held to a stricter standard than any individual cell: a cell may
 * be honestly uncertain, a firm may not. `qualifies` is false unless we hold
 * affirmative evidence of what the firm actually is.
 */
export interface Classification {
  type: FirmType;
  evidence: Evidence[];
  /** Rule ids from docs/INCLUSION_RUBRIC.md that fired for this firm. */
  rulesMatched: string[];
  confidence: number;
  qualifies: boolean;
  note?: string;
}

export type DiscoveryChannel =
  | 'sec_13f'
  | 'sec_13dg'
  | 'sec_form_d'
  | 'sec_adv'
  | 'irs_990pf'
  | 'companies_house'
  | 'state_registry'
  | 'conference_programme'
  | 'job_posting'
  | 'news'
  | 'wealth_first';

/**
 * Kept deliberately separate from Evidence. A source that told us a firm exists
 * is not thereby allowed to tell us what the firm is.
 */
export interface Discovery {
  channel: DiscoveryChannel;
  sourceUrl: string;
  discoveredAt: string;
  /** CIK, EIN, company number - whatever the channel keys on. */
  externalId?: string;
  rawName: string;
}

export interface Signal {
  kind: 'investment' | 'fund_commitment' | 'key_hire' | 'news' | 'filing';
  summary: string;
  /** Undated signals are not intelligence. Records without a date are dropped at emit. */
  occurredAt: string;
  evidence: Evidence;
}

export interface Principal {
  fullName: Cell<string>;
  title: Cell<string>;
  /** Set when a statutory register records this person as controlling the entity. */
  controlBasis?: Cell<string>;
  linkedinUrl: Cell<string>;
  email: Cell<string>;
  phone: Cell<string>;
  location: Cell<string>;
}

export interface FamilyOffice {
  id: string;
  legalName: string;
  /** Every channel that independently surfaced this firm. Length > 1 is corroboration. */
  discoveries: Discovery[];
  classification: Classification;

  description: Cell<string>;
  investmentThesis: Cell<string>;
  sectors: Cell<string[]>;
  aum: Cell<number>;
  website: Cell<string>;
  linkedinUrl: Cell<string>;
  street: Cell<string>;
  postcode: Cell<string>;
  city: Cell<string>;
  region: Cell<string>;
  country: Cell<string>;

  principals: Principal[];
  signals: Signal[];

  createdAt: string;
  updatedAt: string;
}

export function emptyCell<T>(note?: string): Cell<T> {
  return { value: null, status: 'could_not_verify', evidence: [], confidence: 0, note };
}

/** Cells the customer sees. A rejected value in any of these blocks the record at emit. */
export const CUSTOMER_FACING_PATHS = [
  'website',
  'linkedinUrl',
  'principals[].email',
  'principals[].phone',
  'principals[].linkedinUrl',
] as const;
########## packages/core/src/contract/types.ts
import type {
  ClaimStatus,
  CommercialState,
  ContactChannel,
  ContactReaches,
  EvidenceRole,
  GateName,
  GateOutcome,
  RefreshPolicy,
  ReleaseDecisionKind,
  SourceKind,
  SourceTier,
  TrustState,
} from './vocab.js';

/**
 * A source class instance we can fetch from.
 */
export interface Source {
  id: string;
  kind: SourceKind;
  identifier: string;
  baseUrl?: string;
  tier: SourceTier;
  rateLimitPerMin: number;
  lastOkAt?: Date;
  consecutiveFailures: number;
}

/**
 * What a source returned, at a time. Immutable once written.
 *
 * `contentHash` is the whole staleness mechanism: re-fetching and getting the
 * same hash means nothing changed, and a different hash is a concrete reason to
 * re-extract. A clock alone never satisfies the brief's staleness requirement,
 * because "30 days elapsed" is not evidence that anything moved.
 */
export interface Observation {
  id: string;
  sourceId: string;
  url: string;
  fetchedAt: Date;
  contentHash: string;
  /** pointer to the raw body on disk, keyed by contentHash */
  rawRef?: string;
  httpStatus?: number;
  notes?: string;
  /** present in memory during extraction; never persisted on the row */
  body?: string;
}

/**
 * One act of reading one observation and deriving assertions from it.
 *
 * This is the row a claim and its establishing evidence share, and sharing it is
 * what makes the Stage 1 defect unexpressible.
 */
export interface ExtractionEvent {
  id: string;
  runId?: string;
  observationId: string;
  extractor: string;
  startedAt: Date;
  endedAt?: Date;
}

export interface Entity {
  id: string;
  canonicalName: string;
  entityType: string;
  firstSeenAt: Date;
  mergedIntoId?: string;
  trustState: TrustState;
  commercialState: CommercialState;
  /** ADR-11: two metrics, stored separately, never merged into one figure. */
  strictReachable: boolean;
  profileAssistedReachable: boolean;
}

export interface Claim {
  id: string;
  entityId: string;
  extractionEventId: string;
  field: string;
  value: unknown;
  valueType: string;
  status: ClaimStatus;
  confidence: number;
  refreshPolicy: RefreshPolicy;
  establishedAt: Date;
  expiresAt?: Date;
  supersededById?: string;
}

/**
 * The brand.
 *
 * This symbol is deliberately not exported. A module outside this directory can
 * name the `Evidence` type but cannot construct a value that satisfies it --
 * there is no way to write the property. Establishing evidence therefore has
 * exactly one origin in the codebase: the extraction-event writer, which is the
 * only thing that can mint it.
 *
 * The database enforces the same rule independently (PTC-10, the composite
 * foreign key). Two mechanisms, because the type system does not survive a JSON
 * boundary and the database does not catch mistakes at compile time.
 */
declare const EVIDENCE_BRAND: unique symbol;

export interface Evidence {
  id: string;
  claimId: string;
  observationId: string;
  extractionEventId: string;
  role: EvidenceRole;
  /** the exact text read; not a paraphrase and not a summary */
  spanText: string;
  spanStart?: number;
  spanEnd?: number;
  /** the sentence a customer reads. Must describe what was actually checked. */
  method: string;
  createdAt: Date;
  readonly [EVIDENCE_BRAND]: true;
}

/**
 * What a caller supplies. Note there is no claimId, no extractionEventId and no
 * role -- all three are supplied by the writer from the open event, so a caller
 * cannot point evidence at a claim it did not just derive.
 */
export interface EvidenceInput {
  observationId: string;
  spanText: string;
  spanStart?: number;
  spanEnd?: number;
  method: string;
}

export interface ClaimInput {
  entityId: string;
  field: string;
  value: unknown;
  valueType: string;
  confidence?: number;
  refreshPolicy?: RefreshPolicy;
  expiresAt?: Date;
}

/** A claim and the establishing evidence minted with it. Never separable. */
export interface Assertion {
  claim: Claim;
  establishing: Evidence;
}

export interface GateResult {
  gate: GateName;
  outcome: GateOutcome;
  band: 'A' | 'B';
  detail?: string;
  /**
   * What the claim would have been had this gate not fired. A gate whose
   * counterfactual never differs from the outcome is decorative, and §11 reads
   * this field to prove which gates are load-bearing.
   */
  counterfactual?: unknown;
}

export interface ReleaseDecision {
  claimId: string;
  decision: ReleaseDecisionKind;
  gatesPassed: GateName[];
  gatesFailed: GateName[];
  gatesSkipped: GateName[];
  policyVersion: string;
  reason?: string;
}

export interface CommercialDecision {
  entityId: string;
  commercialState: CommercialState;
  reason: string;
  missing: string[];
  policyVersion: string;
}

export interface Contact {
  id: string;
  entityId: string;
  personClaimId?: string;
  channel: ContactChannel;
  value: string;
  reaches: ContactReaches;
  ownershipEvidenceId?: string;
  verificationMethod?: string;
  verifiedAt?: Date;
  status: ClaimStatus;
  countsStrict: boolean;
  countsProfileAssisted: boolean;
}

export interface Signal {
  id: string;
  entityId: string;
  kind: string;
  summary: string;
  occurredAt: Date;
  evidenceId?: string;
  sourceTier: SourceTier;
}
########## packages/core/src/contract/vocab.ts
/**
 * The contract vocabularies, defined once.
 *
 * These mirror the CHECK constraints in packages/db/src/migrations. Keeping them
 * as `as const` tuples rather than TypeScript enums means the union types are
 * derived from the same array the runtime validates against, so a value that
 * type-checks is a value the database will accept.
 */

export const CLAIM_STATUS = [
  'candidate',
  'validated',
  'released',
  'stale',
  'quarantined',
  'retired',
] as const;
export type ClaimStatus = (typeof CLAIM_STATUS)[number];

/**
 * Note what is absent: there is no `withheld`. Commercial sufficiency is judged
 * on the entity, never on the claim -- a claim that passed its trust gates is
 * true regardless of how thin the record around it is. Correction 4.
 */
export const TRUST_STATE = ['active', 'merged', 'quarantined', 'retired'] as const;
export type TrustState = (typeof TRUST_STATE)[number];

export const COMMERCIAL_STATE = ['qualifying', 'withheld', 'unassessed'] as const;
export type CommercialState = (typeof COMMERCIAL_STATE)[number];

/**
 * Evidence roles.
 *
 * `establishing` is the constrained one: exactly one per claim, written inside
 * the claim's own extraction event, never attachable afterwards. The other three
 * attach freely after the fact -- a second source agreeing next week is normal,
 * and a source disagreeing is information we want, not an error.
 */
export const EVIDENCE_ROLE = [
  'establishing',
  'corroborating',
  'conflicting',
  'superseding',
] as const;
export type EvidenceRole = (typeof EVIDENCE_ROLE)[number];

export const SOURCE_KIND = [
  'sec_submissions',
  'sec_13f',
  'sec_fulltext',
  'sec_adv',
  'companies_house',
  'web_page',
  'search_result',
] as const;
export type SourceKind = (typeof SOURCE_KIND)[number];

/** 1 statutory or the firm itself · 2 recognised press · 3 aggregator · 4 unranked */
export type SourceTier = 1 | 2 | 3 | 4;

export const GATE = [
  'schema',
  'attribution',
  'value_type',
  'identity',
  'contact_ownership',
  'coherence',
  'conflict',
  'freshness',
  'commercial',
  'copy',
] as const;
export type GateName = (typeof GATE)[number];

/**
 * Band A gates are cheap and deterministic; all of them run, always, even after
 * one has already failed the claim. Band B is expensive or probabilistic and is
 * skipped once release is impossible.
 *
 * The skip is recorded as `skipped`, never as `passed` -- PTC-2. A gate that did
 * not run must never be able to look like a gate that agreed.
 */
export const BAND_A: readonly GateName[] = [
  'schema',
  'attribution',
  'value_type',
  'contact_ownership',
  'coherence',
] as const;

export const BAND_B: readonly GateName[] = [
  'identity',
  'conflict',
  'freshness',
  'commercial',
  'copy',
] as const;

export const GATE_OUTCOME = ['passed', 'failed', 'skipped', 'error'] as const;
export type GateOutcome = (typeof GATE_OUTCOME)[number];

export const RELEASE_DECISION = ['released', 'quarantined', 'held'] as const;
export type ReleaseDecisionKind = (typeof RELEASE_DECISION)[number];

/**
 * How often a field must be re-observed.
 *
 * `statutory` — registry facts; change rarely, change officially.
 * `volatile` — headcount, AUM, roles; change quietly and often.
 * `append_only` — dated events; never re-verified, they already happened.
 * `derived` — computed from other claims; refreshed when an input moves.
 */
export const REFRESH_POLICY = ['statutory', 'volatile', 'append_only', 'derived'] as const;
export type RefreshPolicy = (typeof REFRESH_POLICY)[number];

export const CONTACT_CHANNEL = ['email', 'phone', 'linkedin', 'postal'] as const;
export type ContactChannel = (typeof CONTACT_CHANNEL)[number];

/** Never inferred from the shape of an address. Always evidenced. */
export const CONTACT_REACHES = ['individual', 'team', 'company', 'unknown'] as const;
export type ContactReaches = (typeof CONTACT_REACHES)[number];

export const RUN_TRIGGER = ['schedule', 'manual', 'retry'] as const;
export type RunTrigger = (typeof RUN_TRIGGER)[number];

export const RUN_JOB = ['discover', 'refresh', 'contract', 'evaluate'] as const;
export type RunJob = (typeof RUN_JOB)[number];

export const RUN_STATUS = [
  'running',
  'completed',
  'failed',
  'halted_budget',
  'aborted',
] as const;
export type RunStatus = (typeof RUN_STATUS)[number];

export const DECISION_KIND = [
  'release',
  'quarantine',
  'supersede',
  'merge',
  'stale',
  'refresh',
  'classify',
  'contact_verify',
  'budget_halt',
  'source_circuit',
  'retry',
] as const;
export type DecisionKind = (typeof DECISION_KIND)[number];
########## packages/core/src/contract/extraction.ts
import { randomUUID } from 'node:crypto';
import type {
  Assertion,
  Claim,
  ClaimInput,
  Evidence,
  EvidenceInput,
  ExtractionEvent,
  Observation,
} from './types.js';
import type { EvidenceRole } from './vocab.js';

/**
 * The only place in the codebase that constructs Evidence.
 *
 * Stage 1 shipped 93 values wearing evidence belonging to a different fact. The
 * mechanism was mundane: evidence was an ordinary array field, so
 * `build-dataset.ts:144` could do `classification.evidence.slice()` and hand the
 * same classification quote to nine unrelated values at assembly time. Nothing
 * in the code objected, because nothing in the code could.
 *
 * The fix is not a rule about where evidence may be assigned. It is that a claim
 * and its establishing evidence are minted together, by one call, from one open
 * event -- so there is no moment at which a claim exists without its basis and
 * could be given someone else's.
 *
 * Three things hold the line, and they fail independently:
 *
 *   1. `Evidence` carries an unexported brand, so no other module can build one.
 *   2. `assert()` is the only function that emits role `establishing`, and it
 *      emits it inseparably from the claim it belongs to.
 *   3. The database refuses the write anyway (composite FK, PTC-10) -- because
 *      the type system does not survive a JSON boundary.
 */

/** Minted with the brand. Local to this module by construction. */
function mintEvidence(
  claimId: string,
  eventId: string,
  role: EvidenceRole,
  input: EvidenceInput,
): Evidence {
  return {
    id: `ev_${randomUUID()}`,
    claimId,
    observationId: input.observationId,
    extractionEventId: eventId,
    role,
    spanText: input.spanText,
    spanStart: input.spanStart,
    spanEnd: input.spanEnd,
    method: input.method,
    createdAt: new Date(),
  } as Evidence;
}

export interface OpenExtractionEvent {
  readonly event: ExtractionEvent;

  /**
   * Derive a value from the observation being read, together with the span that
   * establishes it. The two are returned as one object and written in one
   * transaction; there is no ordering in which the claim exists first.
   *
   * `spanText` must be text actually present in the observation. Gate 2
   * (`attribution`) re-checks that independently -- this signature makes the
   * mistake awkward, the gate makes it detectable.
   */
  assert(claim: ClaimInput, evidence: EvidenceInput): Assertion;

  /**
   * Attach evidence to a claim established elsewhere -- a second source that
   * agrees, one that disagrees, or one that replaces the value.
   *
   * Deliberately cannot express `establishing`: that role is unavailable in this
   * signature's type, so "attach the establishing evidence afterwards" is not a
   * thing a caller can write, whatever they intend.
   */
  attach(
    claimId: string,
    role: Exclude<EvidenceRole, 'establishing'>,
    evidence: EvidenceInput,
  ): Evidence;

  /** Everything derived in this event, for a single transactional write. */
  close(): { event: ExtractionEvent; assertions: Assertion[]; attached: Evidence[] };
}

export function openExtractionEvent(opts: {
  observation: Observation;
  extractor: string;
  runId?: string;
}): OpenExtractionEvent {
  const event: ExtractionEvent = {
    id: `xe_${randomUUID()}`,
    runId: opts.runId,
    observationId: opts.observation.id,
    extractor: opts.extractor,
    startedAt: new Date(),
  };

  const assertions: Assertion[] = [];
  const attached: Evidence[] = [];
  let closed = false;

  const guard = () => {
    // A closed event has already been written. Deriving into it afterwards would
    // produce claims whose evidence never reaches the database -- silently, and
    // only visible later as a claim with no basis.
    if (closed) throw new Error(`extraction event ${event.id} is closed`);
  };

  return {
    event,

    assert(input, evidenceInput) {
      guard();
      if (!evidenceInput.spanText.trim()) {
        throw new Error(`empty span for ${input.field}: evidence must quote something`);
      }
      const claim: Claim = {
        id: `cl_${randomUUID()}`,
        entityId: input.entityId,
        extractionEventId: event.id,
        field: input.field,
        value: input.value,
        valueType: input.valueType,
        status: 'candidate',
        confidence: input.confidence ?? 0,
        refreshPolicy: input.refreshPolicy ?? 'statutory',
        establishedAt: new Date(),
        expiresAt: input.expiresAt,
      };
      const assertion: Assertion = {
        claim,
        establishing: mintEvidence(claim.id, event.id, 'establishing', evidenceInput),
      };
      assertions.push(assertion);
      return assertion;
    },

    attach(claimId, role, evidenceInput) {
      guard();
      const ev = mintEvidence(claimId, event.id, role, evidenceInput);
      attached.push(ev);
      return ev;
    },

    close() {
      guard();
      closed = true;
      event.endedAt = new Date();
      return { event, assertions, attached };
    },
  };
}
