export interface Contact {
  id: string;
  entityId: string;
  personClaimId?: string;
  channel: ContactChannel;
  value: string;
  reaches: ContactReaches;
  ownershipEvidenceId?: string;
  verificationMethod?: string;
  verifiedAt?: Date;
  status: ClaimStatus;
