########## packages/rag/src/agent/tools.ts
import { db, shortlist, type ShortlistQuery } from '@fo/db';

/**
 * The agent's tools (spec §8).
 *
 * Every tool returns `{ data, scope, excluded, limits }`. **Scope is mandatory.**
 * It is what lets the agent state in its answer what was searched and what was
 * left out — which Correction 8 requires of every user-visible sentence, and
 * which Stage 1 failed at when it silently answered a narrower question than the
 * one asked.
 *
 * Every tool reads **released claims only**. Candidate, held, quarantined and
 * withheld data is not reachable from here. That is not a filter the agent
 * applies and could forget; it is the only data these queries select.
 */

export interface ToolResult<T> {
  data: T;
  /** what was searched and what matched */
  scope: Record<string, unknown>;
  /** what was deliberately left out, and why */
  excluded: Array<{ reason: string; count: number }>;
  /** what this tool cannot tell you, stated rather than implied */
  limits: string[];
}

export const TOOL_SCHEMAS = [
  {
    name: 'search_firms',
    description:
      'Shortlist firms over released claims, ranked on fit, evidence, freshness and reachability. ' +
      'Returns why each matched and what it is missing.',
    input_schema: {
      type: 'object' as const,
      properties: {
        q: { type: 'string', description: 'substring match on firm name; NOT semantic' },
        requireStrictReachable: { type: 'boolean', description: 'a route reaching a named individual, profiles excluded' },
        requireProfileAssisted: { type: 'boolean', description: 'as above, counting verified personal profiles (assumption A1)' },
        requiredFields: { type: 'array', items: { type: 'string' }, description: 'e.g. ["principal.fullName","principal.phone"]' },
        freshWithinDays: { type: 'number' },
        maxSourceTier: { type: 'number', description: '1 statutory/self, 2 press, 3 aggregator, 4 unranked' },
        limit: { type: 'number' },
      },
    },
  },
  {
    name: 'get_firm',
    description: "One firm's released claims with the evidence span establishing each. Cannot invent absent fields.",
    input_schema: {
      type: 'object' as const,
      properties: { entityId: { type: 'string' } },
      required: ['entityId'],
    },
  },
  {
    name: 'count_matching',
    description: 'Exact count of firms matching a filter. Never an estimate.',
    input_schema: {
      type: 'object' as const,
      properties: {
        requireStrictReachable: { type: 'boolean' },
        requireProfileAssisted: { type: 'boolean' },
        requiredFields: { type: 'array', items: { type: 'string' } },
      },
    },
  },
  {
    name: 'check_evidence',
    description: 'The gate outcomes and evidence for one claim. Asserts nothing beyond what the gates recorded.',
    input_schema: {
      type: 'object' as const,
      properties: { entityId: { type: 'string' }, field: { type: 'string' } },
      required: ['entityId'],
    },
  },
];

export async function search_firms(input: ShortlistQuery): Promise<ToolResult<unknown>> {
  const r = await shortlist({ ...input, limit: Math.min(input.limit ?? 10, 25) });
  return {
    data: r.results.map((x) => ({
      entityId: x.entityId, name: x.name,
      // Renamed from `score`. The agent presented the old name as a confidence
      // score -- "Colony Family Offices, LLC: 0.9993" -- for a healthcare-LP fit
      // question the dataset cannot answer. It is a ranking weight over fit,
      // evidence grade, freshness and reachability. It is not a probability and
      // says nothing about any particular question.
      relevanceScore: x.score,
      strictReachable: x.strictReachable, profileAssistedReachable: x.profileAssistedReachable,
      contact: x.contact ?? null, matched: x.matched, missing: x.missing,
      lastObservedAt: x.lastObservedAt, bestSourceTier: x.bestSourceTier,
    })),
    scope: {
      searched: r.scope.searched,
      matched: r.scope.matched,
      returned: r.scope.returned,
      appliedFilters: r.scope.appliedFilters,
      relevanceScoreMeaning:
        'relevanceScore ranks how well a record matches the FILTERS APPLIED. It is not a ' +
        'confidence, probability, certainty, likelihood or evidence-strength value, and must ' +
        'never be presented as one. Confidence in any specific question comes from whether the ' +
        'fields that question needs are present -- see each result\'s `missing` list.',
      // Spelled out because a model that reads the array length as "the number
      // of firms" understates the answer. Observed doing exactly that: it
      // reported 10 (the page size) when 24 matched.
      countNote:
        `${r.scope.matched} firms matched; the data array holds only the top ${r.scope.returned}. ` +
        `Report ${r.scope.matched} as the count, never the array length.`,
    },
    excluded: r.scope.excluded,
    limits: r.limits,
  };
}

export async function get_firm(input: { entityId: string }): Promise<ToolResult<unknown>> {
  const sql = db();
  const rows = (await sql`
    SELECT c.field, c.value_json #>> '{}' AS value, c.value_type, c.confidence,
           e.span_text, e.method, o.url, s.tier, o.fetched_at
    FROM s2_claim c
    JOIN s2_evidence e ON e.claim_id = c.id AND e.role = 'establishing'
    JOIN s2_observation o ON o.id = e.observation_id
    JOIN s2_source s ON s.id = o.source_id
    WHERE c.entity_id = ${input.entityId} AND c.status = 'released'
    ORDER BY c.field`) as unknown as Array<Record<string, any>>;

  const ent = (await sql`
    SELECT canonical_name, entity_type, commercial_state, strict_reachable, profile_assisted_reachable
    FROM s2_entity WHERE id = ${input.entityId}`) as unknown as Array<Record<string, any>>;

  // Non-released claims are counted but never shown. The agent is told they
  // exist so it can say "some values did not pass" rather than implying the
  // record is simply thin -- but it cannot read them.
  const [withheld] = (await sql`
    SELECT count(*) FILTER (WHERE status='quarantined')::int quarantined,
           count(*) FILTER (WHERE status='candidate')::int held
    FROM s2_claim WHERE entity_id = ${input.entityId}`) as unknown as Array<Record<string, number>>;

  return {
    data: {
      entity: ent[0] ?? null,
      claims: rows.map((r) => ({
        field: r.field, value: r.value, valueType: r.value_type, confidence: r.confidence,
        evidence: { span: r.span_text, method: r.method, url: r.url, sourceTier: r.tier, observedAt: r.fetched_at },
      })),
    },
    scope: { entityId: input.entityId, releasedClaims: rows.length },
    excluded: [
      ...(withheld?.quarantined ? [{ reason: 'claims quarantined by a gate (not readable here)', count: withheld.quarantined }] : []),
      ...(withheld?.held ? [{ reason: 'claims held pending an unresolved check', count: withheld.held }] : []),
    ],
    limits: [
      'Only released claims are returned. A field absent here is a field this system does not have — not a field the firm lacks.',
      'The evidence span is the exact text read. It is not a summary and has not been paraphrased.',
    ],
  };
}

export async function count_matching(input: {
  requireStrictReachable?: boolean; requireProfileAssisted?: boolean; requiredFields?: string[];
}): Promise<ToolResult<unknown>> {
  const r = await shortlist({ ...input, limit: 1 });
  return {
    data: { count: r.scope.matched },
    scope: { searched: r.scope.searched, appliedFilters: r.scope.appliedFilters },
    excluded: r.scope.excluded,
    limits: ['An exact count over released claims at this moment. Not an estimate and not a projection.'],
  };
}

/**
 * The fields the extractors actually emit.
 *
 * `check_evidence` previously accepted any string. Asked about a contact route
 * the agent invented `contactRoute`, received an empty successful result, and
 * concluded "validation gates did not refuse to publish any information" -- a
 * claim about absence drawn from a query that could not have found anything.
 * An unknown field now fails closed.
 */
export const SUPPORTED_EVIDENCE_FIELDS = [
  'legalName', 'companyNumber', 'companyStatus', 'incorporatedOn', 'cik', 'crd',
  'street', 'city', 'region', 'postcode', 'country',
  'principal.fullName', 'principal.title', 'principal.phone', 'principal.linkedinUrl',
  'officer.fullName', 'officer.postalAddress', 'controller.entityName',
  'latestObservedFilingDate', 'entityClassification',
] as const;

export async function check_evidence(input: { entityId: string; field?: string }): Promise<ToolResult<unknown>> {
  // Validated before the connection is opened: an unknown field is a caller
  // error, and answering it should not require a database at all.
  if (input.field && !SUPPORTED_EVIDENCE_FIELDS.includes(input.field as never)) {
    // A validation error, not an empty result. Zero rows for a field that does
    // not exist is not evidence that nothing was withheld.
    return {
      data: { error: 'unknown_field', requested: input.field, supportedFields: SUPPORTED_EVIDENCE_FIELDS },
      scope: { entityId: input.entityId, field: input.field, validationError: true },
      excluded: [],
      limits: [
        `"${input.field}" is not a field in this dataset, so nothing was checked.`,
        'This result says NOTHING about whether values were withheld for this firm. ' +
        'Re-run with a supported field, or call get_firm first to see which fields exist.',
      ],
    };
  }

  const sql = db();

  // Only the verdict under the newest policy the claim was judged under. An
  // older verdict is history, not the system's current position, and returning
  // both would let the agent quote a superseded outcome as current.
  const rows = (await sql`
    SELECT c.field, c.status, vr.gate, vr.outcome, vr.detail, vr.policy_version
    FROM s2_claim c
    LEFT JOIN LATERAL (
      SELECT DISTINCT ON (v.gate) v.gate, v.outcome, v.detail, v.policy_version
      FROM s2_validation_result v
      WHERE v.claim_id = c.id
      ORDER BY v.gate, v.policy_version DESC
    ) vr ON TRUE
    WHERE c.entity_id = ${input.entityId}
      AND (${input.field ?? null}::text IS NULL OR c.field = ${input.field ?? null})
    ORDER BY c.field, vr.gate`) as unknown as Array<Record<string, any>>;

  return {
    data: rows.map((r) => ({
      field: r.field, claimStatus: r.status, gate: r.gate,
      outcome: r.outcome, detail: r.detail, policyVersion: r.policy_version,
    })),
    scope: {
      entityId: input.entityId,
      field: input.field ?? 'all',
      // Named for what it IS, not for its shape in the database. The composer
      // writes the metric's own name into its prose -- given `rows` it wrote
      // "the evidence check found 54 rows of evidence", which is tool-shaped
      // language a buyer cannot read, and the output guard blocked the whole
      // answer over it. The model was not misbehaving: it emitted the sanctioned
      // count token and the noun came from the key. Same fix as `score` ->
      // `relevanceScore`: change what it is called, not what it may say.
      //
      // Reported as a breakdown and NOT as one total, because a single number is
      // collapsible and the composer collapsed it: given `gateOutcomes: 54` it
      // wrote "the validation gates checked 54 aspects ... all checks were
      // either passed or skipped", for a firm where 84 of 162 outcomes were
      // skipped. Both halves of that are wrong in the same direction -- a
      // skipped gate was not an aspect that got checked, and "passed or
      // skipped" is not a clean bill of health. PTC-2 exists to stop exactly
      // this, and it has to hold in the prose, not only in the database.
      //
      // So the counts arrive already separated. There is no total to quote.
      gatesPassed: rows.filter((r) => r.outcome === 'passed').length,
      gatesSkipped: rows.filter((r) => r.outcome === 'skipped').length,
      gatesFailed: rows.filter((r) => r.outcome === 'failed' || r.outcome === 'error').length,
      gateOutcomesNote:
        'These are three separate figures and must never be added together or ' +
        'described as one count of checks performed. Only `gatesPassed` were ' +
        'actually checked and passed. A skipped gate DID NOT RUN: it is not ' +
        'evidence of anything, it is the absence of evidence, and it must never ' +
        'be presented alongside passes as though the value had been cleared. ' +
        'Describe these as "gate outcomes" or "validation checks", never as ' +
        'rows, records or data.',
    },
    excluded: [],
    limits: [
      'Reports what the gates recorded and nothing beyond it. A passed gate means that specific check passed, not that the value is true.',
      "`skipped` is not `passed`. A skipped gate means the check did not run.",
      'A field this dataset never collects — mandate, sector, allocation, cheque size, AUM, LP ' +
      'appetite — was never seen by a gate and therefore CANNOT have been refused, withheld or ' +
      'blocked. If asked what was refused and nothing was, say so directly: nothing was refused ' +
      'for this firm, and separately, the dataset does not hold those fields for any firm. ' +
      'Calling never-collected data "refused" overstates what the checks did.',
    ],
  };
}

export const TOOLS: Record<string, (input: any) => Promise<ToolResult<unknown>>> = {
  search_firms, get_firm, count_matching, check_evidence,
};
########## packages/rag/src/agent/counts.ts
/**
 * Dataset counts are not generative either.
 *
 * Firm names were made non-generative first; numbers were left alone, and the
 * composer then reported "0 firms matched out of 119 searched" on a query whose
 * tool scope said `matched: 1` and `releasedClaims: 9`. It happened on roughly
 * one run in four. A wrong count is not a rounding error in this product — the
 * whole claim is that every figure traces to something checked.
 *
 * So the composer writes `[[count:search_firms.matched]]` and the server
 * substitutes the integer the tool actually returned. Whatever the model writes
 * about numbers, the digits a reader sees come from the tool output.
 *
 * The validator afterwards is the backstop: any bare number sitting in
 * count-shaped prose that does not correspond to a real metric blocks the
 * answer. Narrowly scoped to dataset metrics — phone numbers, postcodes, years
 * and money in evidence spans are untouched.
 */

export interface MetricRegistry {
  /** e.g. "search_firms.matched" -> 43 */
  values: Map<string, number>;
  /** every legitimate metric value, for the backstop scan */
  known: Set<number>;
}

export function newMetrics(): MetricRegistry {
  return { values: new Map(), known: new Set() };
}

/**
 * Record the countable facts a tool returned.
 *
 * Repeat calls to the same tool get an indexed key as well as the bare one, so
 * `search_firms.matched` stays stable for the common single-call case while a
 * second call is still addressable as `search_firms#2.matched`.
 */
export function recordMetrics(
  reg: MetricRegistry,
  tool: string,
  callIndex: number,
  scope: Record<string, unknown>,
  excluded: Array<{ reason: string; count: number }>,
  data: unknown,
): void {
  const put = (field: string, value: unknown) => {
    if (typeof value !== 'number' || !Number.isFinite(value)) return;
    const bare = `${tool}.${field}`;
    if (!reg.values.has(bare)) reg.values.set(bare, value);
    reg.values.set(`${tool}#${callIndex}.${field}`, value);
    reg.known.add(value);
  };

  // Every count a tool exposes must be registered here or the composer cannot
  // quote it: it emits the token, the resolver does not know the name, and the
  // whole answer is refused for citing an untraceable figure.
  //
  // That refusal is correct and it caught a rename. Splitting `gateOutcomes`
  // into passed/skipped/failed -- so a skipped gate could not be counted as a
  // check -- left the new names unregistered, and Goal 3 blocked on tokens the
  // tool was itself offering. Superseded names stay registered so older traces
  // still resolve.
  for (const field of [
    'searched', 'matched', 'returned', 'releasedClaims', 'offset',
    'gatesPassed', 'gatesSkipped', 'gatesFailed',
    'rows', 'gateOutcomes',
  ]) {
    put(field, scope[field]);
  }
  if (data && typeof data === 'object' && !Array.isArray(data)) {
    put('count', (data as Record<string, unknown>).count);
  }
  if (Array.isArray(data)) put('dataLength', data.length);

  // Only register an exclusion total when there were exclusions. A tool with
  // none would otherwise register 0 as a legitimate figure and whitelist the
  // exact number the composer invented ("0 firms matched").
  if (excluded.length) {
    let excludedTotal = 0;
    for (const e of excluded) {
      excludedTotal += e.count;
      reg.known.add(e.count);
    }
    put('excludedTotal', excludedTotal);
  }
}

/** Tokens the composer may use, with what each means. */
export function tokenRoster(reg: MetricRegistry): string {
  const lines: string[] = [];
  for (const [key, value] of reg.values) {
    if (key.includes('#')) continue; // keep the roster short; indexed keys still resolve
    lines.push(`  [[count:${key}]] = ${value}`);
  }
  return lines.join('\n');
}

const TOKEN=[REDACTED] * Numbers written next to count language. Deliberately narrow: this must not
 * fire on a phone number, a postcode, a year, or a figure inside a quoted
 * evidence span.
 */
const COUNT_NOUN = 'firms?|entities|entity|records?|results?|matches|claims?|rows?|companies|offices';

const COUNT_CONTEXT = new RegExp(
  [
    // "43 firms", "9 claims", "1 of 119 records"
    `\\b(\\d{1,6})\\s+(?:of\\s+)?(?:${COUNT_NOUN})\\b`,
    // "matched: 43", "searched 119"
    `\\b(?:matched|searched|returned|excluded)\\b\\s*[:=]?\\s*(\\d{1,6})\\b`,
    // "43 matched", "8 were excluded"
    `\\b(\\d{1,6})\\s+(?:were\\s+|was\\s+)?(?:matched|searched|returned|excluded)\\b`,
  ].join('|'),
  'gi',
);

export interface CountResolution {
  text: string;
  resolved: Array<{ token: string; value: number }>;
  /** tokens naming a metric no tool produced */
  unresolvedTokens: string[];
  /** bare numbers in count prose that match no metric */
  unsupported: number[];
}

export function resolveCounts(answer: string, reg: MetricRegistry): CountResolution {
  const resolved: Array<{ token: string; value: number }> = [];
  const unresolvedTokens: string[] = [];
  const unsupported: number[] = [];

  const text = answer.replace(TOKEN, (_m, key: string) => {
    const v = reg.values.get(key);
    if (v === undefined) {
      unresolvedTokens.push(key);
      return '(a count no tool produced)';
    }
    resolved.push({ token: key, value: v });
    return String(v);
  });

  // Backstop. A number in count-shaped prose must be one the tools produced.
  for (const m of text.matchAll(COUNT_CONTEXT)) {
    const raw = m[1] ?? m[2] ?? m[3];
    if (raw === undefined) continue;
    const n = Number(raw);
    if (!Number.isFinite(n)) continue;
    if (reg.known.has(n)) continue;
    if (!unsupported.includes(n)) unsupported.push(n);
  }

  return { text, resolved, unresolvedTokens, unsupported };
}
########## packages/rag/src/agent/names.ts
/**
 * Firm names are not generative.
 *
 * In production the agent wrote "BARRINGTON COMPANIES MANAGEMENT, LLC" when the
 * dataset holds "BARINGTON" — one letter, invented on the way out of the
 * composer while the tool data underneath was correct. For a product whose whole
 * claim is that every value traces to evidence, a firm name the model typed from
 * memory is a fabricated value, however small the edit.
 *
 * So the composer never writes firm names at all. It writes `[[entityId]]`
 * tokens, and the server substitutes the stored `legalName`. A name that does
 * not exist in the tool output cannot be produced, because the model is not the
 * thing producing names.
 *
 * The scan afterwards is the backstop for a model that ignores the instruction:
 * anything that still looks like a firm name is matched against the canonical
 * set, near-misses are corrected to the stored spelling, and anything with no
 * match at all blocks the answer.
 */

/** Tokens that make a capitalised phrase look like a company rather than prose. */
const COMPANYISH =
  /\b(LLC|L\.L\.C\.?|LTD|LIMITED|INC|INCORPORATED|CORP|CORPORATION|COMPANY|CO|PLC|GMBH|LP|L\.P\.?|LLP|PARTNERS|HOLDINGS?|CAPITAL|MANAGEMENT|INVESTMENTS?|VENTURES?|GROUP|TRUST|OFFICE)\b/i;

/** A run of capitalised / all-caps words, i.e. a plausible firm mention. */
const CANDIDATE = /\b([A-Z][A-Za-z&'’.-]*(?:[ ,]+(?:[A-Z][A-Za-z&'’.-]*|of|and|the|for)){0,7}(?:,?\s*(?:LLC|L\.L\.C\.?|LTD|LIMITED|INC\.?|CORP\.?|L\.P\.?|LP|LLP|PLC))?)/g;

/**
 * A legal suffix ends a firm name, so the comma after it separates list items
 * rather than continuing one name.
 *
 * Without this the matcher swallows "Timonier Family Office, LTD., Virtus Family
 * Office LLC" as a single phrase, finds no firm by that name, and blocks an
 * answer in which every firm was real. Over-blocking a correct answer is worse
 * than the misspelling this guard exists to catch.
 */
const LIST_BREAK = /(?<=\b(?:LLC|L\.L\.C\.?|LTD\.?|LIMITED|INC\.?|CORP\.?|L\.P\.?|LP|LLP|PLC))\s*[,;]\s+(?=[A-Z])/g;

/** Trailing punctuation is sentence grammar, not part of the stored name. */
function trimEdges(s: string): string {
  return s.replace(/^[\s,;.]+/, '').replace(/[\s,;]+$/, '').replace(/\.$/, '');
}

export function normaliseName(s: string): string {
  return s
    .toUpperCase()
    .replace(/[.,'’&-]/g, ' ')
    .replace(/\b(L\s*L\s*C|L\s*P|LLP|INC|CORP|CORPORATION|COMPANY|CO|LTD|LIMITED|PLC|THE)\b/g, ' ')
    .replace(/[^A-Z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Cheap edit distance, capped — only used to decide "did they mean this one?" */
function editDistance(a: string, b: string): number {
  if (Math.abs(a.length - b.length) > 4) return 99;
  const prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  const cur = new Array<number>(b.length + 1);
  for (let i = 1; i <= a.length; i++) {
    cur[0] = i;
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(
        prev[j]! + 1,
        cur[j - 1]! + 1,
        prev[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1),
      );
    }
    for (let j = 0; j <= b.length; j++) prev[j] = cur[j]!;
  }
  return prev[b.length]!;
}

export interface NameResolution {
  text: string;
  /** names silently corrected to their stored spelling */
  corrected: Array<{ wrote: string; stored: string }>;
  /** firm-like names with no counterpart in the tool output at all */
  fabricated: string[];
  /** [[entityId]] tokens the tools never returned */
  unresolvedTokens: string[];
}

/**
 * Substitute `[[entityId]]` tokens, then audit whatever prose remains.
 *
 * `canonical` is entityId -> stored legalName, built only from tool output. If a
 * name is not in here it did not come from the data.
 */
export function resolveNames(answer: string, canonical: Map<string, string>): NameResolution {
  const corrected: Array<{ wrote: string; stored: string }> = [];
  const fabricated: string[] = [];
  const unresolvedTokens: string[] = [];

  // 1. the intended path: tokens in, stored names out
  let text = answer.replace(/\[\[([^\]]+)\]\]/g, (_m, id: string) => {
    const key = String(id).trim();
    const name = canonical.get(key);
    if (name) return name;
    unresolvedTokens.push(key);
    return '(a firm the tools did not return)';
  });

  if (canonical.size === 0) return { text, corrected, fabricated, unresolvedTokens };

  const byNorm = new Map<string, string>();
  for (const name of canonical.values()) byNorm.set(normaliseName(name), name);
  const exact = new Set(canonical.values());

  // 2. Account for every stored name that actually appears, before judging
  //    anything. Segmenting prose into firm mentions with a regex proved
  //    unreliable in both directions -- it swallowed comma-separated lists of
  //    real firms as one phantom name, and its suffix list was case-sensitive.
  //
  //    Inverting is sturdier: mark the spans that ARE stored names, then only
  //    scrutinise what is left over. A real name can never be flagged, because
  //    it is matched before the scan runs.
  const consumed: Array<[number, number]> = [];
  const claim = (from: number, len: number) => consumed.push([from, from + len]);
  const overlaps = (from: number, to: number) =>
    consumed.some(([a, b]) => from < b && to > a);

  for (const stored of [...exact].sort((a, b) => b.length - a.length)) {
    const needle = stored.toLowerCase();
    let at = text.toLowerCase().indexOf(needle);
    while (at !== -1) {
      if (!overlaps(at, at + stored.length)) claim(at, stored.length);
      at = text.toLowerCase().indexOf(needle, at + 1);
    }
  }

  // 3. Whatever firm-like prose remains was written by the model, not taken
  //    from the data. Correct a near miss to the stored spelling; flag anything
  //    with no counterpart at all.
  //    Claimed spans are masked character-for-character rather than skipped.
  //    Skipping a candidate that merely *touches* a known name would let a
  //    fabricated firm hide behind a real one in the same sentence — the
  //    greedy match spans both, overlaps, and gets waved through. Masking keeps
  //    offsets intact while making the real names unmatchable.
  const MASK = '\u0001';
  let masked = text;
  for (const [a, b] of consumed) {
    masked = masked.slice(0, a) + MASK.repeat(b - a) + masked.slice(b);
  }

  const rewrites: Array<{ from: number; to: number; text: string }> = [];
  for (const m of masked.matchAll(CANDIDATE)) {
    const raw = m[0];
    const at = m.index ?? 0;
    if (raw.includes(MASK)) continue;
    if (!COMPANYISH.test(raw)) continue;

    const phrase = trimEdges(raw);
    if (!phrase) continue;
    const offset = at + raw.indexOf(phrase);
    if (overlaps(offset, offset + phrase.length)) continue;

    const norm = normaliseName(phrase);
    if (!norm) continue;

    const hit = byNorm.get(norm);
    if (hit) {
      corrected.push({ wrote: phrase, stored: hit });
      rewrites.push({ from: offset, to: offset + phrase.length, text: hit });
      claim(offset, phrase.length);
      continue;
    }

    let best: { name: string; d: number } | null = null;
    for (const [n, name] of byNorm) {
      const d = editDistance(norm, n);
      if (!best || d < best.d) best = { name, d };
    }
    if (best && best.d <= Math.max(2, Math.floor(norm.length * 0.12))) {
      corrected.push({ wrote: phrase, stored: best.name });
      rewrites.push({ from: offset, to: offset + phrase.length, text: best.name });
      claim(offset, phrase.length);
      continue;
    }

    fabricated.push(phrase);
  }

  for (const r of rewrites.sort((a, b) => b.from - a.from)) {
    text = text.slice(0, r.from) + r.text + text.slice(r.to);
  }

  return { text, corrected, fabricated, unresolvedTokens };
}

