50	  countsResolved: Array<{ token: string; value: number }>;
51	  /** relevance scores the draft presented as confidence, if any */
52	  relevanceAsConfidence: Array<{ value: number; context: string }>;
53	  /** tool internals the draft leaked into prose, if any */
54	  toolInternalsLeaked: string[];
55	  /** absence-of-withholding claims with no completed check behind them */
56	  unsupportedAbsence: string[];
57	  /** skipped gates presented as checks that cleared the record */
58	  skippedAsChecked: string[];
59	  /** the composer's own instructions quoted back to the reader */
60	  promptLeak: string[];
61	  /** a refusal asserted where nothing was actually refused */
62	  unsupportedRefusal: string[];
63	  /** measured spend and wall time for this answer -- see @fo/core/meter */
64	  cost: Record<string, unknown>;
65	}
66	
67	interface Plan {
68	  constraints: Array<{ constraint: string; honourable: boolean; why: string }>;
69	  calls: Array<{ tool: string; input: Record<string, unknown>; because: string }>;
70	}
71	
72	const MAX_CALLS = 4;
73	
74	/** Tools whose input names one entity, so they cannot run before a search. */
75	const ID_TOOLS = new Set(['get_firm', 'check_evidence']);
76	
77	/**
78	 * Pull entityId -> stored legalName out of whatever a tool returned.
79	 *
80	 * This map is the ONLY source of firm names in the final answer. If a name is
81	 * not in here it did not come from the data.
82	 */
83	function harvest(data: unknown, into: Map<string, string>): void {
84	  const add = (id: unknown, name: unknown) => {
85	    if (typeof id === 'string' && typeof name === 'string' && id && name) into.set(id, name);
86	  };
87	  if (Array.isArray(data)) {
88	    for (const row of data) {
89	      if (row && typeof row === 'object') add((row as any).entityId, (row as any).name);
90	    }
91	  } else if (data && typeof data === 'object') {
92	    const d = data as any;
93	    if (d.entity?.canonical_name) {
94	      // get_firm returns the entity without echoing its id; the caller knows it.
95	      add(d.entityId ?? d.entity?.id, d.entity.canonical_name);
96	    }
97	  }
98	}
99	
100	const PLAN_PROMPT = (question: string) => `You are planning how to answer a question about a family-office dataset.
101	
102	You may ONLY use these tools. They read released, gate-passed claims:
103	${TOOL_SCHEMAS.map((t) => `- ${t.name}: ${t.description}\n  input: ${JSON.stringify(t.input_schema.properties)}`).join('\n')}
104	
105	Question: "${question}"
106	
107	First, break the question into its explicit constraints. For EACH, say whether the
108	tools can honour it exactly.
109	
110	Mark honourable=false when the dataset cannot express the constraint. Examples of
111	constraints that are NOT honourable: filtering by assets under management, by
112	investment sector or mandate, by number of employees, by founding family surname,
113	by anything requiring semantic similarity rather than a name substring.
114	
115	Being honest that a constraint cannot be honoured is CORRECT and expected. Do not
116	claim you can honour something to look capable.
117	
118	Then list up to ${MAX_CALLS} tool calls.
119	
120	Return JSON:
121	{"constraints":[{"constraint":"...","honourable":true,"why":"..."}],
122	 "calls":[{"tool":"search_firms","input":{...},"because":"..."}]}`;
123	
124	const COMPOSE_PROMPT = (question: string, results: string, unhonoured: string[], roster: string, counts: string) => `Answer the question using ONLY the tool results below.
125	
126	Question: "${question}"
127	
128	Tool results:
129	${results}
130	
131	${unhonoured.length ? `You could NOT honour these constraints:
132	${unhonoured.map((c) => `- ${c}`).join('\n')}
133	
134	You MUST state this plainly in your answer, in the first two sentences, in plain
135	words. Say which part of the question you could not do and what you did instead.
136	An answer that quietly ignores these is worse than no answer.` : 'All constraints were honourable.'}
137	
138	Rules:
139	- NEVER write a firm's name. Refer to each firm by its exact token from this
140	  roster, copied character for character:
141	${roster || '  (no firms were returned)'}
142	  The server substitutes the stored legal name. Do not invent a token, do not
143	  write the words "entityId", and do not type a firm name yourself — you will get
144	  its spelling wrong, and a misspelled firm name is a fabricated value.
145	- Never upgrade a label: a company inbox is not a principal's email; "not found" is not "does not exist".
146	- State the scope: how many were searched, how many MATCHED. Use the "matched"
147	  number from the tool scope, never the length of the returned data array - the
148	  array is a truncated page, and reporting its length understates the answer.
149	- NEVER type a number for how many firms matched, were searched, were excluded,
150	  are reachable, or how many claims or evidence rows exist. Use these tokens,
151	  copied exactly:
152	${counts || '  (no counts available)'}
153	  The server substitutes the figure the tool actually returned. A number you type
154	  yourself is a guess, and a wrong count is a fabricated fact.
155	- Numbers that are NOT dataset counts — phone numbers, postcodes, dates, values
156	  quoted inside evidence — you may write normally.
157	- relevanceScore is a RANKING WEIGHT over the filters applied. NEVER call it
158	  confidence, probability, certainty, likelihood or evidence strength, and never
159	  convert it to a percentage and present it as one.
160	- If asked how confident you are, confidence comes from whether the fields THAT
161	  QUESTION needs are present. If the evidence for the specific question is absent
162	  — no mandate, sector, allocation, cheque size or LP data — say confidence is
163	  low, or that fit cannot be confidently determined, and say which evidence is
164	  missing. Do not invent a percentage.
165	- You may offer a narrowed proxy shortlist ONLY after stating plainly what was
166	  unavailable and which narrower criteria you actually used instead.
167	- Write for a non-technical buyer. Never expose tool internals: no "rows",
168	  "dataLength", "entityId", "null", "0 data" or similar.
169	- If a firm is missing a field, say it is missing. Do not estimate it.
170	- Be concise and specific. No preamble.
171	
172	Return JSON: {"answer":"..."}`;
173	
174	export async function runAgent(question: string): Promise<AgentAnswer> {
175	  // Per-answer, so a goal trace carries what that goal actually cost rather than
176	  // a share of some daily total. Reset first: the process is long-lived on
177	  // Vercel and would otherwise accumulate across unrelated questions.
178	  resetMeter();
179	  const startedAt = Date.now();
180	  const trace: AgentTrace[] = [];
181	  const now = () => new Date().toISOString();
182	  const push = (kind: AgentTrace['kind'], detail: unknown) =>
183	    trace.push({ step: trace.length + 1, kind, detail, at: now() });
184	  const cost = () => ({ ...meterSnapshot(), wallMs: Date.now() - startedAt });
185	
186	  // ---- plan --------------------------------------------------------------
187	  const plan = await generateJson<Plan>(PLAN_PROMPT(question), {
188	    type: 'object',
189	    properties: {
190	      constraints: { type: 'array', items: { type: 'object' } },
191	      calls: { type: 'array', items: { type: 'object' } },
192	    },
193	  });
194	  push('plan', plan);
195	
196	  const unhonoured = (plan.constraints ?? [])
197	    .filter((c) => !c.honourable)
198	    .map((c) => `${c.constraint} — ${c.why}`);
199	
200	  // ---- act, in two phases ------------------------------------------------
201	  //
202	  // The planner runs once, before any tool has executed, so it cannot know an
203	  // entityId that only exists after a search. In production it filled the gap
204	  // with the literal string "<firm_id>" and both ID-dependent calls returned
205	  // nothing. A tool call with a placeholder argument is not a call, it is a
206	  // wasted round trip that can be misread as "this firm has no data".
207	  //
208	  // So discovery tools run first, real ids are harvested from what they return,
209	  // and ID-dependent tools run only afterwards and only with an id that exists.
210	  const toolsUsed: string[] = [];
211	  const scope: Record<string, unknown>[] = [];
212	  const collected: string[] = [];
213	  const canonical = new Map<string, string>();
214	  const metrics = newMetrics();
215	  const relevanceScores: number[] = [];
216	  // What check_evidence actually managed to check. A call that returned a
217	  // validation error checked nothing, and the difference decides whether the
218	  // answer may say anything about what was withheld.
219	  const evidenceChecks: Array<EvidenceCheck & { collectedAt?: number }> = [];
220	  // Only get_firm knows what was quarantined or held for an entity, and that
221	  // is what decides whether a refusal claim is supportable.
222	  const withheldByEntity = new Map<string, number>();
223	  let callIndex = 0;
224	
225	  const runTool = async (tool: string, input: Record<string, unknown>) => {
226	    const fn = TOOLS[tool];
227	    if (!fn) { push('tool', { tool, error: 'no such tool' }); return; }
228	    try {
229	      const r: ToolResult<unknown> = await fn(input);
230	      toolsUsed.push(tool);
231	      scope.push({ tool, ...r.scope });
232	      push('tool', { tool, input, scope: r.scope, excluded: r.excluded, rows: Array.isArray(r.data) ? r.data.length : 1 });
233	      harvest(r.data, canonical);
234	      if (tool === 'check_evidence') {
235	        evidenceChecks.push({
236	          entityId: String(input.entityId ?? ''),
237	          field: input.field === undefined ? undefined : String(input.field),
238	          completed: (r.scope as Record<string, unknown>).validationError !== true,
239	          // Where this call's text lands in `collected`, so a superseded failure
240	          // can be withdrawn from what the composer reads.
241	          collectedAt: collected.length,
242	        });
243	      }
244	      recordMetrics(metrics, tool, ++callIndex, r.scope, r.excluded, r.data);
245	      if (Array.isArray(r.data)) {
246	        for (const row of r.data as Array<Record<string, unknown>>) {
247	          if (typeof row?.relevanceScore === 'number') relevanceScores.push(row.relevanceScore);
248	        }
249	      }
250	      collected.push(
251	        `TOOL ${tool}(${JSON.stringify(input)})\n` +
252	        `scope: ${JSON.stringify(r.scope)}\n` +
253	        `excluded: ${JSON.stringify(r.excluded)}\n` +
254	        `limits: ${r.limits.join(' | ')}\n` +
255	        `data: ${JSON.stringify(r.data).slice(0, 4000)}`,
256	      );
257	    } catch (err) {
258	      push('tool', { tool, error: err instanceof Error ? err.message : String(err) });
259	    }
260	  };
261	
262	  const calls = (plan.calls ?? []).slice(0, MAX_CALLS);
263	  const discovery = calls.filter((c) => !ID_TOOLS.has(c.tool));
264	  const needsId = calls.filter((c) => ID_TOOLS.has(c.tool));
265	
266	  for (const call of discovery) await runTool(call.tool, (call.input ?? {}) as Record<string, unknown>);
267	
268	  // The sequence has to be guaranteed, not merely policed. A plan can consist
269	  // entirely of ID-dependent calls with a firm NAME where an id belongs, in
270	  // which case refusing them all leaves nothing to answer from. Seeding the
271	  // search the planner omitted turns a dead run into a correct one, and the
272	  // seeded call is recorded in the trace like any other.
273	  if (!discovery.length && needsId.length) {
274	    const hint = needsId
275	      .map((c) => String((c.input as Record<string, unknown> | undefined)?.entityId ?? ''))
276	      .find((v) => v && !v.startsWith('ent_') && !v.startsWith('<'));
277	    if (hint) {
278	      push('plan', { seeded: 'search_firms', reason: 'plan had no discovery call; ID-dependent tools cannot run without one', q: hint });
279	      await runTool('search_firms', { q: hint, limit: 5 });
280	    }
281	  }
282	
283	  for (const call of needsId) {
284	    const asked = String((call.input as Record<string, unknown> | undefined)?.entityId ?? '');
285	    // Accept only an id the tools actually returned. Otherwise fall back to the
286	    // top discovery result, and if there is none, skip and say so in the trace.
287	    const entityId = canonical.has(asked) ? asked : [...canonical.keys()][0];
288	    if (!entityId) {
289	      push('tool', { tool: call.tool, skipped: 'no real entity id available; refused to call with a placeholder', asked });
290	      continue;
291	    }
292	    if (entityId !== asked) {
293	      push('tool', { tool: call.tool, rebound: { from: asked || '(none)', to: entityId }, why: 'planner supplied a placeholder or unknown id' });
294	    }
295	    await runTool(call.tool, { ...(call.input as Record<string, unknown>), entityId });
296	  }
297	
298	  // A check_evidence call that failed validation left a hole where a real check
299	  // should be, and every remaining defence only *stops* the composer answering
300	  // past it. Repairing the call is what lets the question actually be answered:
301	  // the field was invented, so the call is re-run without one, which is the
302	  // supported way to ask "what did the gates record for this firm". Same pattern
303	  // as seeding the discovery call the planner omitted -- fix the plan, in the
304	  // trace, rather than compose around the gap.
305	  for (const c of evidenceChecks.filter((x) => !x.completed)) {
306	    if (evidenceChecks.some((x) => x.entityId === c.entityId && x.completed)) continue;
307	    push('tool', {
308	      tool: 'check_evidence',
309	      repaired: { from: c.field ?? '(none)', to: '(all fields)' },
310	      why: 'the requested field does not exist, so nothing was checked; re-running the supported form',
311	    });
312	    await runTool('check_evidence', { entityId: c.entityId });
313	  }
314	
315	  // Withdraw superseded failures from what the composer reads.
316	  //
317	  // A failed call's text is emphatic by design -- "this result says NOTHING
318	  // about whether values were withheld" -- and it appeared once per invented
319	  // field. Against two of those, the single repaired result lost: the composer
320	  // reported "I could not determine what the gates refused, the dataset does not
321	  // support those fields" while holding 54 real gate outcomes it had just been
322	  // handed. Honest, and wrong about what it knew.
323	  //
324	  // A superseded failure is not a finding. It stays in the trace, which is the
325	  // audit record; `collected` is the working set, and a question that was
326	  // answered on the second attempt was answered.
327	  const superseded = new Set<number>();
328	  for (const c of evidenceChecks) {
329	    if (c.completed || c.collectedAt === undefined) continue;
330	    if (evidenceChecks.some((x) => x.entityId === c.entityId && x.completed)) {
331	      superseded.add(c.collectedAt);
332	    }
333	  }
334	  if (superseded.size) {
335	    const withdrawn = [...superseded].sort((a, b) => b - a);
336	    for (const i of withdrawn) collected.splice(i, 1);
337	    push('compose', {
338	      withdrewSupersededResults: withdrawn.length,
339	      why: 'a failed check that was repaired is not a finding; it stays in the trace, not in the answer',
340	    });
341	  }
342	
343	  if (!collected.length) {
344	    const answer =
345	      'I could not retrieve anything for this question. No tool call succeeded, so I have nothing to base an answer on.';
346	    push('compose', { answer, reason: 'no tool results' });
347	    return { answer, unhonouredConstraints: unhonoured, blocked: false, toolsUsed, scope, trace, nameCorrections: [], countsResolved: [], relevanceAsConfidence: [], toolInternalsLeaked: [], unsupportedAbsence: [], skippedAsChecked: [], promptLeak: [], unsupportedRefusal: [], cost: cost() };
348	  }
349	
350	  // ---- compose -----------------------------------------------------------
351	  // The exact tokens, so the model copies rather than composes them. Given only
352	  // a format example it wrote the literal string "[[entityId]]".
353	  const roster = [...canonical.entries()]
354	    .slice(0, 40)
355	    .map(([id, name]) => `  [[${id}]] = ${name}`)
356	    .join('\n');
357	
358	  // Kept so the guard can compare the answer against what was asked of the
359	  // model. A leak is only detectable against the actual prompt text.
360	  const composePrompt = COMPOSE_PROMPT(
361	    question, collected.join('\n\n'), unhonoured, roster, tokenRoster(metrics));
362	  const composed = await generateJson<{ answer: string }>(
363	    composePrompt,
364	    { type: 'object', properties: { answer: { type: 'string' } } },
365	  );
366	  const rawAnswer = composed.answer ?? '';
367	  push('compose', { answer: rawAnswer });
368	
369	  // ---- firm names become non-generative -----------------------------------
370	  const counts = resolveCounts(rawAnswer, metrics);
371	  const resolved = resolveNames(counts.text, canonical);
372	  let answer = resolved.text;
373	  const nameCorrections = resolved.corrected;
374	  const countsResolved = counts.resolved;
375	  if (counts.unresolvedTokens.length || counts.unsupported.length) {
376	    push('block', {
377	      stage: 'count-resolution',
378	      unresolvedTokens: counts.unresolvedTokens,
379	      unsupported: counts.unsupported,
380	    });
381	  }
382	  if (resolved.corrected.length || resolved.fabricated.length || resolved.unresolvedTokens.length) {
383	    push('block', {
384	      stage: 'name-resolution',
385	      corrected: resolved.corrected,
386	      fabricated: resolved.fabricated,
387	      unresolvedTokens: resolved.unresolvedTokens,
388	    });
389	  }
390	
391	  // ---- claims audit: relevance-as-confidence, and leaked internals --------
392	  // The answer must restate the unhonourable constraints and may restate the
393	  // question; neither counts as quoting its instructions.
394	  // What the answer is SUPPOSED to reproduce, and therefore cannot be leaking:
395	  // the tool results it exists to convey, the constraints it must state, and the
396	  // question. Comparing against the whole prompt flagged an answer for quoting
397	  // its own retrieved data, which is the opposite of a leak. What is left to
398	  // match against is the instruction scaffolding -- the only part addressed to
399	  // the system rather than the reader.
400	  const claims = auditClaims(
401	    answer, relevanceScores,
402	    evidenceChecks.map((c) => ({ ...c, withheldForEntity: withheldByEntity.get(c.entityId) ?? 0 })),
403	    composePrompt, [...unhonoured, question, ...collected]);
404	  const relevanceAsConfidence = claims.relevanceAsConfidence;
405	  const toolInternalsLeaked = claims.internals;
406	  const unsupportedAbsence = claims.unsupportedAbsence;
407	  const skippedAsChecked = claims.skippedAsChecked;
408	  const promptLeak = claims.promptLeak;
409	  const unsupportedRefusal = claims.unsupportedRefusal;
410	  if (relevanceAsConfidence.length || toolInternalsLeaked.length || unsupportedAbsence.length || skippedAsChecked.length || promptLeak.length || unsupportedRefusal.length) {
411	    push('block', {
412	      stage: 'claims-audit',
413	      relevanceAsConfidence, toolInternalsLeaked, unsupportedAbsence, skippedAsChecked, promptLeak, unsupportedRefusal,
414	    });
415	  }
416	
417	  // ---- the constraint-preservation check, in control flow ----------------
418	  //
419	  // Not a prompt instruction and not a suggestion. If the planner recorded a
420	  // constraint it could not honour, the answer must visibly say so, or it does
421	  // not ship. This is the check Stage 1 did not have.
422	  let blocked = false;
423	  let blockReason: string | undefined;
424	
425	  // A ranking weight presented as confidence is a fabricated certainty, and
426	  // tool internals are unreadable to a buyer. Either blocks the answer.
427	  if (relevanceAsConfidence.length || toolInternalsLeaked.length || unsupportedAbsence.length || skippedAsChecked.length || promptLeak.length || unsupportedRefusal.length) {
428	    blocked = true;
429	    blockReason =
430	      (relevanceAsConfidence.length ? 'composer presented a relevance score as a confidence value' : '') +
431	      (relevanceAsConfidence.length && toolInternalsLeaked.length ? '; ' : '') +
432	      (toolInternalsLeaked.length ? 'composer exposed internal tool output in customer-facing prose' : '') +
433	      ((relevanceAsConfidence.length || toolInternalsLeaked.length) && unsupportedAbsence.length ? '; ' : '') +
434	      (unsupportedAbsence.length ? 'composer asserted nothing was withheld with no completed evidence check behind it' : '') +
435	      ((relevanceAsConfidence.length || toolInternalsLeaked.length || unsupportedAbsence.length) && skippedAsChecked.length ? '; ' : '') +
436	      (skippedAsChecked.length ? 'composer counted gates that did not run as checks that cleared the record' : '') +
437	      ((relevanceAsConfidence.length || toolInternalsLeaked.length || unsupportedAbsence.length || skippedAsChecked.length) && promptLeak.length ? '; ' : '') +
438	      (promptLeak.length ? 'composer quoted its own instructions into the answer' : '') +
439	      (promptLeak.length && unsupportedRefusal.length ? '; ' : '') +
440	      (unsupportedRefusal.length ? 'composer said values were refused when nothing was refused' : '');
441	    answer = confidenceBlockMessage(claims);
442	    return { answer, unhonouredConstraints: unhonoured, blocked, blockReason, toolsUsed, scope, trace,
443	      nameCorrections, countsResolved, relevanceAsConfidence, toolInternalsLeaked, unsupportedAbsence, skippedAsChecked, promptLeak, unsupportedRefusal, cost: cost() };
444	  }
445	
446	  // A dataset count the tools did not produce is a fabricated fact.
447	  if (counts.unresolvedTokens.length || counts.unsupported.length) {
448	    blocked = true;
449	    blockReason =
450	      `composer stated ${counts.unsupported.length} dataset count(s) no tool produced` +
451	      (counts.unresolvedTokens.length ? ` and ${counts.unresolvedTokens.length} unresolved count token(s)` : '');
452	    answer =
453	      'I cannot give this answer. The draft stated ' +
454	      [...counts.unsupported.map(String), ...counts.unresolvedTokens].map((c) => `"${c}"`).join(', ') +
455	      ' as a figure from the data, but no tool returned it. Rather than show you a ' +
456	      'number I cannot trace, I am declining the answer.';
457	    return { answer, unhonouredConstraints: unhonoured, blocked, blockReason, toolsUsed, scope, trace, nameCorrections, countsResolved, relevanceAsConfidence, toolInternalsLeaked, unsupportedAbsence, skippedAsChecked, promptLeak, unsupportedRefusal, cost: cost() };
458	  }
459	
460	  // A firm-like name with no counterpart in the tool output is a fabricated
461	  // value. It does not ship, even if everything around it is correct.
462	  if (resolved.fabricated.length || resolved.unresolvedTokens.length) {
463	    blocked = true;
464	    blockReason =
465	      `composer produced ${resolved.fabricated.length} firm name(s) and ` +
466	      `${resolved.unresolvedTokens.length} entity reference(s) that no tool returned`;
467	    answer =
468	      'I cannot give this answer. The draft named ' +
469	      [...resolved.fabricated, ...resolved.unresolvedTokens].map((f) => `"${f}"`).join(', ') +
470	      ', which does not appear in the data I retrieved. Rather than show you a firm ' +
471	      'that may not exist, I am declining the answer.';
472	    return { answer, unhonouredConstraints: unhonoured, blocked, blockReason, toolsUsed, scope, trace, nameCorrections, countsResolved, relevanceAsConfidence, toolInternalsLeaked, unsupportedAbsence, skippedAsChecked, promptLeak, unsupportedRefusal, cost: cost() };
473	  }
474	
475	  if (unhonoured.length) {
476	    const surfaced = surfacesLimitation(answer, unhonoured);
477	    if (!surfaced) {
478	      blocked = true;
479	      blockReason =
480	        'composer produced an answer that did not surface a constraint the planner could not honour';
481	      push('block', { blockReason, unhonoured });
482	      answer =
483	        `I could not fully answer this as asked. ` +
484	        `${unhonoured.map((u) => u.split(' — ')[0]).join('; ')} — the dataset does not hold that, so I did not filter on it.\n\n` +
485	        `What I can tell you, on the part I could answer:\n\n${answer}`;
486	    }
487	  }
488	
489	  return { answer, unhonouredConstraints: unhonoured, blocked, blockReason, toolsUsed, scope, trace, nameCorrections, countsResolved, relevanceAsConfidence, toolInternalsLeaked, unsupportedAbsence, skippedAsChecked, promptLeak, unsupportedRefusal, cost: cost() };
490	}
491	
492	/**
493	 * Does the answer actually tell the reader about the limitation?
494	 *
495	 * Deliberately lexical rather than a model judgement: asking a model whether an
496	 * answer is honest enough reintroduces exactly the failure mode this guards. A
497	 * cheap check that is occasionally over-strict is the right trade — a false
498	 * block prepends a caveat, while a false pass ships a silently narrowed answer.
499	 */
500	export function surfacesLimitation(answer: string, unhonoured: string[]): boolean {
501	  const a = answer.toLowerCase();
502	
503	  const admits = [
504	    'could not', "couldn't", 'cannot', "can't", 'unable', 'do not hold', "don't hold",
505	    'not available', 'no data', 'does not contain', "doesn't contain", 'not held',
506	    'did not filter', "didn't filter", 'no claim', 'not recorded', 'unavailable',
507	    'i have no', 'the dataset does not', 'not something',
508	  ].some((p) => a.includes(p));
509	  if (!admits) return false;
510	
511	  // It must also point at the right subject, not merely sound apologetic.
512	  return unhonoured.some((u) => {
513	    const subject = u.split(' — ')[0]!.toLowerCase();
514	    const words = subject.split(/[^a-z]+/).filter((w) => w.length > 4);
515	    return words.length === 0 || words.some((w) => a.includes(w));
516	  });
517	}
