1	/**
2	 * Two deterministic output guards, both written against real production failures.
3	 *
4	 * ### 1. A relevance score is not a confidence score
5	 *
6	 * Asked the verbatim Goal 2 question — best fit for a lower-middle-market
7	 * healthcare services fund seeking LPs — the agent correctly said the dataset
8	 * cannot express sector, mandate or market size, and then wrote:
9	 *
10	 *   "Confidence scores are Colony Family Offices, LLC: 0.9993"
11	 *
12	 * That number is the shortlist's ranking weight over fit, evidence grade,
13	 * freshness and reachability. Colony holds no sector, AUM or mandate claim, so
14	 * 99.93% confidence in a healthcare-LP fit rests on nothing. The answer
15	 * contradicted its own first sentence.
16	 *
17	 * Renaming the field helps and does not settle it, because the model can still
18	 * relabel. This is the part that cannot be talked past.
19	 *
20	 * ### 2. Tool internals are not buyer-facing language
21	 *
22	 * "Validation gates did not refuse to publish any information, with 0 rows and
23	 * 0 data." A non-technical buyer cannot read that, and the brief requires every
24	 * user-visible state to be understandable to one.
25	 *
26	 * ### 3. A failed check is not a clean result
27	 *
28	 * Same Goal 3 answer, the part that survived the first fix. The agent called
29	 * `check_evidence` with an invented field, got nothing back, and reported that
30	 * nothing had been withheld. Making the tool fail closed stopped it returning a
31	 * misleading empty success -- and the composer wrote the same conclusion anyway,
32	 * now on top of an explicit validation error.
33	 *
34	 * Absence is the hardest thing for a retrieval system to assert honestly and the
35	 * most damaging to get wrong: "nothing was withheld" is a stronger claim than
36	 * any value the system publishes, and here it was a claim about a query that
37	 * could not have found anything. So it is no longer left to the composer. An
38	 * absence-of-withholding sentence is permitted only when a `check_evidence` call
39	 * actually completed for that firm, and the run repairs the failed call before
40	 * composing rather than composing around the hole.
41	 */
42	
43	const CONFIDENCE_WORD =
44	  /\b(confidence|confident|probability|probable|certainty|certain|likelihood|likely|evidence strength|strength of evidence|assurance|reliability score)\b/i;
45	
46	/** Tool-shaped phrasing that must never reach a customer. */
47	const TOOL_INTERNALS = [
48	  /\b\d+\s+rows?\b/i,
49	  // Database vocabulary in plain English, which the token list above misses
50	  // because these are real words. "a qualifying firm with a commercial state"
51	  // and "listed in the 'missing' field for each firm" both reached production:
52	  // the first is a column name, the second tells a buyer to read a JSON key.
53	  // camelCase is not English. Every tool parameter and scope key is written this
54	  // way and none of them mean anything to a buyer: "I could not honor the
55	  // requireProfileAssisted=true constraint or the freshWithinDays=0 constraint"
56	  // reached production. One rule covers the whole class, including keys added
57	  // later, which a hand-maintained list would keep missing.
58	  /\b[a-z]+[A-Z][a-zA-Z]*\b/,
59	  /\bexcluded total\b/i,
60	  /\bcommercial[_ ]?state\b/i,
61	  /\btrust[_ ]?state\b/i,
62	  /\bcommercial floor\b/i,
63	  /\b['"`]?missing['"`]?\s+field\b/i,
64	  /\bthe\s+['"`]\w+['"`]\s+field\b/i,
65	  // The system's own action attributed to the reader: "You could not honour the
66	  // constraint" tells a buyer that THEY failed at something.
67	  /\byou\s+(?:could\s*n[o']?t|couldn't|did\s*n[o']?t|didn't|cannot|can't|were\s+unable\s+to)\s+(?:honour|honor|determine|answer|provide|retrieve|express)\b/i,
68	  /\b(rows?|dataLength|releasedClaims|excludedTotal|appliedFilters|entityId|value_?type|claim_?id|policy_?version)\b/,
69	  /\b0\s+data\b/i,
70	  /\bnull\b/,
71	  /\bundefined\b/,
72	  /\[\[|\]\]/,
73	];
74	
75	/**
76	 * Sentences asserting that nothing was refused, withheld, blocked or quarantined.
77	 *
78	 * Matched on the pairing of a negation with a withholding verb, so "nothing was
79	 * withheld" and "no values were refused" are caught while "nine values were
80	 * withheld" -- a true, supported statement -- is not.
81	 */
82	// `n't` carries no leading word boundary -- in "didn't" the preceding character
83	// is a word character, so \bn't\b never matches. Contractions are how a model
84	// most naturally phrases this, so missing them would miss the common case.
85	const NEGATION = String.raw`(?:\b(?:no|nothing|none|not|never)\b|n't)`;
86	const WITHHOLD = String.raw`\b(?:withheld|withhold|withholding|refused|refuse|refusing|blocked|block|blocking|quarantined|quarantine|suppressed|suppress|held back|kept back|excluded|exclude)\b`;
87	
88	const ABSENCE_OF_WITHHOLDING = new RegExp(
89	  `${NEGATION}[^.;!?]{0,80}${WITHHOLD}` +
90	  `|${WITHHOLD}[^.;!?]{0,40}\\b(?:nothing|no (?:values?|claims?|fields?|information|data)|none)\\b`,
91	  'i',
92	);
93	
94	/**
95	 * Claiming the system refused something it never had.
96	 *
97	 * Production, Goal 3: *"The evidence that was refused to be published includes
98	 * the mandate, sector, allocation, cheque size, and LP data, as these fields are
99	 * not present."* Boston holds 9 claims, all released, none quarantined, and no
100	 * firm anywhere in the dataset has a mandate, sector or allocation field. The
101	 * gates never saw those values, so they cannot have refused them.
102	 *
103	 * This is the mirror of the absence defect and it fails the brief's own test
104	 * from the other side: *"not found through the sources attempted" may not be
105	 * shown as "does not exist"* -- and equally, never collected may not be shown as
106	 * withheld. It is the more flattering direction to be wrong in, because it makes
107	 * the validation layer look busier than it was, which is why it needs a guard
108	 * rather than trust.
109	 */
110	/**
111	 * The agent saying it could not work something out.
112	 *
113	 * "I could not determine the validation gates' refusal reasons" contains the
114	 * word `refusal` and asserts the opposite of a refusal having happened -- it is
115	 * the agent reporting its own limit, which is the behaviour this system wants.
116	 * Blocking it inverted the guard's purpose.
117	 *
118	 * Deliberately narrow: it needs the agent's own inability verb. The sentence
119	 * this guard exists for -- "the evidence that WAS refused to be published
120	 * includes the mandate, sector ..." -- contains no such construction and is
121	 * still caught.
122	 */
123	const CANNOT_DETERMINE =
124	  /\b(?:could\s*n[o']?t|couldn't|cannot|can't|unable to|not able to|do(?:es)?\s*n[o']?t know)\s+(?:\w+\s+){0,2}?(determine|establish|tell|find|say|report|provide|identify|verify)\b/i;
125	
126	const ASSERTS_REFUSAL =
127	  /\b(refus\w+|withh\w+|suppress\w+|blocked|quarantin\w+|declined to publish|held back|kept back)\b/i;
128	
129	export interface EvidenceCheck {
130	  entityId: string;
131	  /** false when the call returned a validation error and checked nothing */
132	  completed: boolean;
133	  field?: string;
134	  /** gates that actually ran and passed */
135	  passed?: number;
136	  /** gates that did not run at all */
137	  skipped?: number;
138	  /** gates that actually failed -- the only thing that refuses a value */
139	  failed?: number;
140	  /** claims quarantined or held for this entity, from get_firm's `excluded` */
141	  withheldForEntity?: number;
142	}
143	
144	/**
145	 * Treating a gate that did not run as one that cleared the value.
146	 *
147	 * Two shapes, both produced in the same sentence: an all-clear that names
148	 * skipping as one of its grounds ("all checks were either passed or skipped"),
149	 * and a count of what was "checked" that only reconciles if skips are counted
150	 * as checks.
151	 *
152	 * PTC-2 keeps `skipped` and `passed` apart in the database. This keeps them
153	 * apart in the sentence a buyer reads, which is the only place it matters to
154	 * them.
155	 */
156	const SKIP_AS_CLEARANCE =
157	  /\b(pass(?:ed|es)?|clear(?:ed)?|fine|ok|satisfactor\w+|success\w*)\b[^.;!?]{0,30}\bor\b[^.;!?]{0,20}\bskip(?:ped)?\b|\bskip(?:ped)?\b[^.;!?]{0,30}\bor\b[^.;!?]{0,20}\b(pass(?:ed|es)?|clear(?:ed)?)\b/i;
158	
159	/**
160	 * A sentence that names the skips as not having run is the honest form, not the
161	 * defect. "A further 84 did not run, so those aspects are unverified" states
162	 * exactly what this guard is trying to force, and must not be blocked for
163	 * containing a number larger than the pass count.
164	 */
165	const NAMES_THE_SKIP =
166	  /\b(did ?n[o']t run|did not run|were not run|was not run|never ran|not (?:checked|run|verified|validated|performed)|skipped|unverified|unchecked|no[t]? applicable)\b/i;
167	
168	const CHECKED_A_COUNT = /\b(check\w*|validat\w*|verif\w*|review\w*|examin\w*|assess\w*)\b[^.;!?]{0,40}?(\d+)|(\d+)\s+[^.;!?]{0,30}?\b(checks?|aspects?|validations?|gates?)\b/i;
169	
170	/**
171	 * The answer quoting its own instructions.
172	 *
173	 * Production, Goal 3: *"I could not honour these constraints: You could NOT
174	 * honour these constraints: - Unpublished information ... You MUST state this
175	 * plainly in your answer, in the first two sentences, in plain words. Say which
176	 * part of the question you could not do and what you did instead."*
177	 *
178	 * A buyer was shown the prompt. Nothing else caught it: the internals guard
179	 * looks for tool-shaped tokens and this is English, the absence guard had
180	 * nothing to fire on, and the sentence is not false -- it is just not addressed
181	 * to the reader.
182	 *
183	 * Detected structurally rather than by phrase list, because the next leak will
184	 * be worded differently: a run of `LEAK_WINDOW` consecutive words shared with
185	 * the prompt is a quotation, not a coincidence.
186	 *
187	 * But a long overlap alone is not enough, and assuming it was produced a false
188	 * block. The prompt's own rules name the fields whose absence the answer is
189	 * supposed to report -- "no mandate, sector, allocation, cheque size or LP data"
190	 * -- so an answer doing exactly that shares eight words with its instructions
191	 * while leaking nothing. Domain vocabulary is shared by definition; what a
192	 * reader must never see is the prompt's VOICE, so the overlap must also carry an
193	 * imperative addressed to the system.
194	 */
195	const LEAK_WINDOW = 8;
196	
197	/** Second-person direction. Present in scaffolding, absent from a noun list. */
198	const INSTRUCTION_VOICE =
199	  /\b(you must|you may not|you should|you will|never |do not |don't |always |must not|copied exactly|copied character|use these tokens|say which|state the scope|refer to each|return json|your answer|in your answer)\b/i;
200	
201	const shingles = (text: string, n: number): Set<string> => {
202	  const words = text.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean);
203	  const out = new Set<string>();
204	  for (let i = 0; i + n <= words.length; i++) out.add(words.slice(i, i + n).join(' '));
205	  return out;
206	};
207	
208	/**
209	 * Runs of the prompt that appear verbatim in the answer.
210	 *
211	 * `expectedEchoes` are the parts of the prompt the answer is SUPPOSED to
212	 * reproduce: the unhonourable constraints, which it is required to state
213	 * plainly, and the question itself. Those are content the prompt carries, not
214	 * instructions it gives, and matching them is the guard working correctly at the
215	 * wrong target -- it blocked Goals 2 and 3 for doing exactly what was asked.
216	 * They are removed before comparison, so what remains to match against is the
217	 * instruction scaffolding, which is the only part no reader should ever see.
218	 */
219	export function findPromptLeak(
220	  answer: string,
221	  promptText: string,
222	  expectedEchoes: string[] = [],
223	): string[] {
224	  if (!promptText) return [];
225	  let instructionsOnly = promptText;
226	  for (const echo of expectedEchoes) {
227	    if (echo.trim().length < 4) continue;
228	    instructionsOnly = instructionsOnly.split(echo).join(' ');
229	  }
230	  const fromPrompt = shingles(instructionsOnly, LEAK_WINDOW);
231	  const hits: string[] = [];
232	  for (const s of shingles(answer, LEAK_WINDOW)) {
233	    if (!fromPrompt.has(s)) continue;
234	    // Shared wording only matters when it carries the instruction's voice.
235	    if (!INSTRUCTION_VOICE.test(s)) continue;
236	    hits.push(s);
237	  }
238	  // Overlapping shingles describe one leak; report the distinct starts only.
239	  return hits.filter((h, i) => !hits.some((o, j) => j < i && o.includes(h.split(' ')[0]!))).slice(0, 3);
240	}
241	
242	export interface ClaimsAudit {
243	  /** relevance values presented as confidence */
244	  relevanceAsConfidence: Array<{ value: number; context: string }>;
245	  /** tool internals leaking into prose */
246	  internals: string[];
247	  /** an assertion that nothing was withheld, with no completed check behind it */
248	  unsupportedAbsence: string[];
249	  /** a skipped gate presented as one that checked or cleared the value */
250	  skippedAsChecked: string[];
251	  /** runs of the composer's own instructions quoted back to the reader */
252	  promptLeak: string[];
253	  /** a refusal asserted where nothing was actually refused */
254	  unsupportedRefusal: string[];
255	}
256	
257	/**
258	 * Does the answer present a relevance score as a confidence?
259	 *
260	 * Deliberately lexical. Asking a model whether an answer conflates the two
261	 * reintroduces the judgement that failed in the first place.
262	 *
263	 * A number counts as a relevance score if it matches one the tools returned,
264	 * either as the raw value (0.9993) or as a percentage (99.93). It counts as
265	 * *presented as confidence* if a confidence word appears within 120 characters —
266	 * enough to span "Confidence scores are X: 0.9993, Y: 0.9984" without reaching
267	 * into an unrelated sentence..
268	 */
269	export function auditClaims(
270	  answer: string,
271	  relevanceScores: number[],
272	  evidenceChecks: EvidenceCheck[] = [],
273	  promptText = '',
274	  expectedEchoes: string[] = [],
275	): ClaimsAudit {
276	  const relevanceAsConfidence: Array<{ value: number; context: string }> = [];
277	  const seen = new Set<number>();
278	
279	  if (relevanceScores.length) {
280	    const wanted = new Map<string, number>();
281	    for (const s of relevanceScores) {
282	      wanted.set(s.toFixed(4).replace(/0+$/, '').replace(/\.$/, ''), s);
283	      wanted.set(s.toFixed(3), s);
284	      wanted.set(s.toFixed(2), s);
285	      wanted.set((s * 100).toFixed(2).replace(/\.?0+$/, ''), s);
286	      wanted.set((s * 100).toFixed(1).replace(/\.0$/, ''), s);
287	      wanted.set(String(Math.round(s * 100)), s);
288	    }
289	
290	    for (const m of answer.matchAll(/\d+(?:\.\d+)?/g)) {
291	      const raw = m[0];
292	      const score = wanted.get(raw) ?? wanted.get(raw.replace(/0+$/, '').replace(/\.$/, ''));
293	      if (score === undefined) continue;
294	      const at = m.index ?? 0;
295	      const window = answer.slice(Math.max(0, at - 120), Math.min(answer.length, at + 60));
296	      if (CONFIDENCE_WORD.test(window) && !seen.has(score)) {
297	        seen.add(score);
298	        relevanceAsConfidence.push({ value: score, context: window.replace(/\s+/g, ' ').trim() });
299	      }
300	    }
301	  }
302	
303	  const internals: string[] = [];
304	  for (const re of TOOL_INTERNALS) {
305	    const hit = re.exec(answer);
306	    if (hit && !internals.includes(hit[0])) internals.push(hit[0]);
307	  }
308	
309	  // An absence claim needs a check that ran. A check that errored is not weaker
310	  // evidence of absence -- it is none, and the two must not be treated alike.
311	  // When no check_evidence call was attempted at all this stays silent: that is
312	  // a different answer shape, judged by the tool-coverage rules, not here.
313	  const unsupportedAbsence: string[] = [];
314	  if (evidenceChecks.length && !evidenceChecks.some((c) => c.completed)) {
315	    for (const sentence of answer.split(/(?<=[.!?])\s+/)) {
316	      if (ABSENCE_OF_WITHHOLDING.test(sentence)) unsupportedAbsence.push(sentence.trim());
317	    }
318	  }
319	
320	  // Only meaningful when gates were actually skipped. With no skips there is
321	  // nothing to misrepresent, and "all checks passed" is simply true.
322	  const skipped = evidenceChecks.reduce((n, c) => n + (c.skipped ?? 0), 0);
323	  const passed = evidenceChecks.reduce((n, c) => n + (c.passed ?? 0), 0);
324	  const skippedAsChecked: string[] = [];
325	  if (skipped > 0) {
326	    for (const sentence of answer.split(/(?<=[.!?])\s+/)) {
327	      if (SKIP_AS_CLEARANCE.test(sentence)) {
328	        skippedAsChecked.push(sentence.trim());
329	        continue;
330	      }
331	      // A count of what was "checked" is only honest at the number that passed.
332	      // Anything larger is reconciling by counting gates that never ran.
333	      if (NAMES_THE_SKIP.test(sentence)) continue;
334	      const m = CHECKED_A_COUNT.exec(sentence);
335	      const n = m ? Number(m[2] ?? m[3]) : NaN;
336	      if (!Number.isFinite(n) || n <= passed) continue;
337	      // "Of 54 validation checks, 26 passed" names the true total alongside the
338	      // pass count, which discloses the gap rather than hiding it. Only a count
339	      // larger than what passed AND presented without that context is inflation.
340	      const inSentence = new Set((sentence.match(/\d+/g) ?? []).map(Number));
341	      if (n === passed + skipped && inSentence.has(passed)) continue;
342	      skippedAsChecked.push(sentence.trim());
343	    }
344	  }
345	
346	  // A refusal claim is only supportable when something was actually refused: a
347	  // gate that failed, or a claim quarantined or held. With neither, the sentence
348	  // is describing data that was never collected.
349	  const refused = evidenceChecks.reduce((n, c) => n + (c.failed ?? 0) + (c.withheldForEntity ?? 0), 0);
350	  const unsupportedRefusal: string[] = [];
351	  if (evidenceChecks.length && refused === 0) {
352	    for (const sentence of answer.split(/(?<=[.!?])\s+/)) {
353	      if (!ASSERTS_REFUSAL.test(sentence)) continue;
354	      // The agent reporting that IT could not work something out is not a claim
355	      // that the system refused anything.
356	      if (CANNOT_DETERMINE.test(sentence)) continue;
357	      // "nothing was withheld" is the absence guard's business, not this one.
358	      if (ABSENCE_OF_WITHHOLDING.test(sentence)) continue;
359	      // No exemption for also mentioning absence. The production sentence said
360	      // the values were "refused to be published ... as these fields are not
361	      // present" -- both at once, which is not a softer version of the claim but
362	      // a self-contradicting one. The honest form does not use the word refused:
363	      // "the dataset does not record these, so there was nothing to publish".
364	      unsupportedRefusal.push(sentence.trim());
365	    }
366	  }
367	
368	  // Paired disclosure. Citing the pass count while silently dropping the skips
369	  // is true and still misleading: "the validation gates passed 26 checks" reads
370	  // as "this record was checked" when 28 of 54 never ran, and it does so in the
371	  // one answer whose whole subject is what validation did.
372	  //
373	  // Numeric rather than lexical, on purpose -- the wording-based rules here have
374	  // needed two corrections and this one only has to compare integers. Either the
375	  // skip count or the total discloses the gap, so either satisfies it.
376	  if (skipped > 0 && passed > 0) {
377	    const numbers = new Set((answer.match(/\d+/g) ?? []).map(Number));
378	    if (numbers.has(passed) && !numbers.has(skipped) && !numbers.has(passed + skipped)) {
379	      skippedAsChecked.push(
380	        `states ${passed} checks passed without disclosing the ${skipped} that did not run`,
381	      );
382	    }
383	  }
384	
385	  return {
386	    relevanceAsConfidence, internals, unsupportedAbsence, skippedAsChecked, unsupportedRefusal,
387	    promptLeak: findPromptLeak(answer, promptText, expectedEchoes),
388	  };
389	}
390	
391	/**
392	 * What a blocked answer says instead.
393	 *
394	 * It states the failure rather than silently softening the wording, because a
395	 * quietly rewritten answer is indistinguishable from one that was right.
396	 */
397	export function confidenceBlockMessage(audit: ClaimsAudit): string {
398	  const parts: string[] = ['I cannot give this answer as drafted.'];
399	  if (audit.relevanceAsConfidence.length) {
400	    parts.push(
401	      `It presented a search-ranking value (${audit.relevanceAsConfidence.map((r) => r.value).join(', ')}) ` +
402	      'as a confidence score. That number ranks how well a record matched the filters applied; it is ' +
403	      'not a measure of confidence in the question you asked, and the dataset does not hold the ' +
404	      'mandate, sector or allocation evidence that question would need.',
405	    );
406	  }
407	  if (audit.internals.length) {
408	    parts.push(`It also exposed internal tool output (${audit.internals.join(', ')}) rather than plain language.`);
409	  }
410	  if (audit.unsupportedRefusal.length) {
411	    parts.push(
412	      `It said the system refused to publish something — "${audit.unsupportedRefusal[0]}" — when ` +
413	      'nothing was refused for this firm. Those values were never collected, which is a different ' +
414	      'thing from being withheld, and reporting one as the other overstates what the checks did.',
415	    );
416	  }
417	  if (audit.promptLeak.length) {
418	    parts.push(
419	      `It quoted its own instructions back to you — "...${audit.promptLeak[0]}...". ` +
420	      'That text was addressed to the system, not to you, and should never have appeared in an answer.',
421	    );
422	  }
423	  if (audit.skippedAsChecked.length) {
424	    parts.push(
425	      `It reported gates that did not run as though they had cleared the record — ` +
426	      `"${audit.skippedAsChecked[0]}". A skipped gate is the absence of a check, not a passing one, ` +
427	      'and counting it toward an all-clear is the one thing this system must never do.',
428	    );
429	  }
430	  if (audit.unsupportedAbsence.length) {
431	    parts.push(
432	      'It stated that nothing had been withheld — ' +
433	      `"${audit.unsupportedAbsence[0]}" — when the check that would establish that did not run. ` +
434	      'I do not know whether anything was withheld for this firm, and saying otherwise would be ' +
435	      'the one claim in this system a buyer could not verify for themselves.',
436	    );
437	  }
438	  return parts.join(' ');
439	}
