57	export interface ShortlistResult {
58	  entityId: string;
59	  name: string;
60	  score: number;
61	  dimensions: {
62	    fit: number;
63	    evidence: number;
64	    freshness: number;
65	    reachability: number;
66	  };
67	  /** the concrete reasons this row is here */
68	  matched: string[];
69	  /** what a buyer would want and this record does not have */
70	  missing: string[];
71	  strictReachable: boolean;
72	  profileAssistedReachable: boolean;
73	  releasedFields: string[];
74	  contact?: { channel: string; value: string; reaches: string; method: string | null };
75	  lastObservedAt: string | null;
76	  bestSourceTier: number | null;
77	}
78	
79	export interface ShortlistResponse {
80	  results: ShortlistResult[];
81	  /**
82	   * Mandatory. What was searched, what matched, what was excluded and why.
83	   * Correction 8: the system states its scope rather than letting the reader
84	   * assume the answer covers everything.
85	   */
86	  scope: {
87	    searched: number;
88	    matched: number;
89	    returned: number;
90	    /** how many matches were skipped before this page */
91	    offset: number;
92	    /** the offset for the next page, or null when this is the last one */
93	    nextOffset: number | null;
94	    excluded: Array<{ reason: string; count: number }>;
95	    appliedFilters: string[];
96	  };
97	  /** honest statements about what this retrieval cannot do */
98	  limits: string[];
99	  query: ShortlistQuery;
100	}
