105	export async function shortlist(raw: ShortlistQuery): Promise<ShortlistResponse> {
106	  // Callers -- the agent planner in particular -- emit 0 as a "no value"
107	  // sentinel for these. Taken literally they are unsatisfiable: nothing is 0
108	  // days old, and there is no source tier 0, so either silently excluded every
109	  // record. Worse, `appliedFilters` tested truthiness, so the filter ran without
110	  // being disclosed and the scope under-reported what had been applied.
111	  //
112	  // Normalising here keeps one rule: a filter that runs is a filter that is
113	  // reported, and a value that cannot constrain anything is not a filter.
114	  const query: ShortlistQuery = {
115	    ...raw,
116	    freshWithinDays: raw.freshWithinDays && raw.freshWithinDays > 0 ? raw.freshWithinDays : undefined,
117	    maxSourceTier: raw.maxSourceTier && raw.maxSourceTier >= 1 ? raw.maxSourceTier : undefined,
118	    requiredFields: raw.requiredFields?.length ? raw.requiredFields : undefined,
119	    q: raw.q?.trim() || undefined,
120	  };
121	  const limit = Math.min(query.limit ?? 25, 100);
