133	           (SELECT max(o.fetched_at) FROM s2_claim c
134	              JOIN s2_extraction_event xe ON xe.id = c.extraction_event_id
135	              JOIN s2_observation o ON o.id = xe.observation_id
136	             WHERE c.entity_id = e.id AND c.status = 'released')            AS last_observed,
137	           (SELECT min(s.tier) FROM s2_claim c
138	              JOIN s2_extraction_event xe ON xe.id = c.extraction_event_id
139	              JOIN s2_observation o ON o.id = xe.observation_id
140	              JOIN s2_source s ON s.id = o.source_id
141	             WHERE c.entity_id = e.id AND c.status = 'released')            AS best_tier,
142	           (SELECT count(*)::int FROM s2_claim c
143	             WHERE c.entity_id = e.id AND c.status = 'released')            AS released_count,
144	           ct.channel, ct.value AS contact_value, ct.reaches, ct.verification_method
145	    FROM s2_entity e
146	    LEFT JOIN LATERAL (
147	      SELECT channel, value, reaches, verification_method
148	      FROM s2_contact
149	      WHERE entity_id = e.id AND status = 'released' AND counts_profile_assisted
150	      ORDER BY counts_strict DESC LIMIT 1
151	    ) ct ON TRUE
