153	    -- product reported 664 searched against a file of 663 without this.
154	    WHERE e.trust_state = 'active' AND e.merged_into_id IS NULL
155	  `) as unknown as Array<Record<string, any>>;
156	
157	  const searched = rows.length;
158	  const excluded: Array<{ reason: string; count: number }> = [];
159	  const bump = (reason: string) => {
160	    const hit = excluded.find((e) => e.reason === reason);
161	    if (hit) hit.count++;
162	    else excluded.push({ reason, count: 1 });
163	  };
