169	  if (query.requireProfileAssisted) appliedFilters.push('profile-assisted reachability');
170	  if (query.requiredFields?.length) appliedFilters.push(`holds ${query.requiredFields.join(', ')}`);
171	  if (query.freshWithinDays != null) appliedFilters.push(`observed within ${query.freshWithinDays}d`);
172	  if (query.maxSourceTier != null) appliedFilters.push(`source tier <= ${query.maxSourceTier}`);
173	
174	  const now = Date.now();
175	  const kept: ShortlistResult[] = [];
176	
