1	/**
2	 * The grounding control.
3	 *
4	 * The brief is explicit that prompt instructions are not enough - telling a model
5	 * to use only the provided data does not prove it will. So the answer is never
6	 * generated as prose. The model must emit discrete claims, each citing the chunk
7	 * ids it rests on, and every claim is then checked here before anything reaches
8	 * the user.
9	 *
10	 * Two checks, in order of cost:
11	 *
12	 *   1. Lexical. The claim's content words must actually occur in the chunks it
13	 *      cites. Cheap, deterministic, and catches the common failure where a model
14	 *      cites a real chunk for a fact that chunk does not contain.
15	 *
16	 *   2. Entailment, on a different provider from the one that wrote the claim.
17	 *      A model asked to check its own output shares its own blind spots.
18	 *
19	 * A claim that fails is dropped, not flagged. Rendering an unsupported claim with
20	 * a warning still puts it in front of the user.
21	 */
22	import { verifyJson } from './llm.js';
23	
24	export interface Claim {
25	  text: string;
26	  citedChunkIds: string[];
27	}
28	
29	export interface SourceChunk {
30	  id: string;
31	  content: string;
32	  firmName: string;
33	}
34	
35	export interface CheckedClaim extends Claim {
36	  supported: boolean;
37	  reason: string;
38	}
39	
40	export interface AttributionResult {
41	  kept: CheckedClaim[];
42	  dropped: CheckedClaim[];
43	}
44	
45	const STOP = new Set([
46	  'the','a','an','and','or','of','in','on','at','to','for','with','is','are','was','were','be','been','has','have',
47	  'had','it','its','this','that','these','those','their','they','which','as','by','from','also','more','than','who',
48	]);
49	
50	function contentWords(s: string): string[] {
51	  return s
52	    .toLowerCase()
53	    .replace(/[^a-z0-9\s.]/g, ' ')
54	    .split(/\s+/)
55	    .filter((w) => w.length > 2 && !STOP.has(w));
56	}
57	
