77	  return coverage >= 0.6 ? { ok: true, missing: [] } : { ok: false, missing: [`only ${Math.round(coverage * 100)}% of terms appear in the cited sources`] };
78	}
79	
80	interface EntailmentResponse {
81	  results: Array<{ index: number; supported: boolean; reason: string }>;
82	}
83	
84	async function entailmentCheck(claims: Claim[], corpusFor: (c: Claim) => string): Promise<Map<number, { supported: boolean; reason: string }>> {
85	  const out = new Map<number, { supported: boolean; reason: string }>();
