89	    .map((c, i) => `[${i}] CLAIM: ${c.text}\n    SOURCES: ${corpusFor(c).slice(0, 1200)}`)
90	    .join('\n\n');
91	
92	  try {
93	    const res = await verifyJson<EntailmentResponse>(
94	      `You are auditing claims against the source text each one cites. You did not write these claims.
95	
96	For each numbered claim decide whether the cited sources FULLY support it.
97	
98	Mark supported=false if the claim:
99	- states anything the sources do not say, however plausible
100	- is more specific than the sources (an exact figure where sources give a range)
101	- asserts a relationship, cause, or ranking the sources do not state
102	- generalises from one source to a broader population
103	
104	Mark supported=true only if every part of the claim is directly stated in its sources.
105	
106	${body}
107	
108	Return JSON only, in this shape, covering every claim:
109	{"results":[{"index":0,"supported":true,"reason":"..."}]}`,
110	    );
111	    for (const r of res.results ?? []) {
112	      out.set(r.index, { supported: Boolean(r.supported), reason: r.reason ?? '' });
113	    }
114	  } catch (err) {
