125	  const byId = new Map(chunks.map((c) => [c.id, c]));
126	  const corpusFor = (c: Claim) =>
127	    c.citedChunkIds
128	      .map((id) => byId.get(id))
129	      .filter(Boolean)
130	      .map((s) => `${s!.firmName}: ${s!.content}`)
131	      .join('\n');
132	
133	  const kept: CheckedClaim[] = [];
134	  const dropped: CheckedClaim[] = [];
135	  const needEntailment: Claim[] = [];
136	  const lexicalPassIndex: number[] = [];
137	
138	  claims.forEach((claim) => {
139	    if (claim.citedChunkIds.length === 0) {
140	      dropped.push({ ...claim, supported: false, reason: 'claim cites no source' });
141	      return;
142	    }
143	    const corpus = corpusFor(claim);
144	    if (!corpus) {
145	      dropped.push({ ...claim, supported: false, reason: 'cited sources were not among those retrieved' });
146	      return;
147	    }
148	    const lex = lexicalSupport(claim.text, corpus);
149	    if (!lex.ok) {
150	      dropped.push({ ...claim, supported: false, reason: `not found in cited sources: ${lex.missing.join(', ')}` });
151	      return;
152	    }
153	    lexicalPassIndex.push(needEntailment.length);
154	    needEntailment.push(claim);
155	  });
156	
157	  const entail = await entailmentCheck(needEntailment, corpusFor);
158	
159	  needEntailment.forEach((claim, i) => {
160	    const verdict = entail.get(i) ?? { supported: false, reason: 'not audited' };
161	    if (verdict.supported) kept.push({ ...claim, supported: true, reason: 'verified against cited sources' });
