1	/**
2	 * Answer orchestration.
3	 *
4	 * The pipeline is: parse constraints -> retrieve under those constraints ->
5	 * generate discrete claims that cite chunk ids -> audit every claim -> decide
6	 * whether what survived is worth showing.
7	 *
8	 * The system declines rather than guesses in three situations, all of which are
9	 * ordinary rather than exceptional:
10	 *   - retrieval found nothing within the user's constraints
11	 *   - what it found is too far from the question to be about it
12	 *   - the claims the model wrote did not survive the audit
13	 *
14	 * A declined answer is a correct answer. The brief asks for a control that makes
15	 * the system qualify, limit, or decline when evidence is insufficient, and a
16	 * control that never fires is not a control.
17	 */
18	import { retrieve, getFirms, countMatching, firmsNamedIn, logQuery, type RetrievedChunk } from '@fo/db';
19	import type { RequestedField } from './query.js';
20	import { checkAttribution, type Claim, type CheckedClaim } from './attribution.js';
21	import { parseQuery, type ParsedQuery } from './query.js';
22	import { embed, generateJson, ServiceUnavailable } from './llm.js';
23	
24	export interface FirmSummary {
25	  id: string;
26	  name: string;
27	  type: string;
28	  typeConfidence: number;
29	  location: string;
30	  phone: string | null;
31	  email: string | null;
32	  website: string | null;
33	  principal: string | null;
34	  principalTitle: string | null;
35	  principalControl: string | null;
36	  description: string | null;
37	  linkedin: string | null;
38	  principalLinkedin: string | null;
39	  otherPrincipals: Array<{ name: string; title: string }>;
40	  address: string | null;
41	  latestSignal: { summary: string; date: string } | null;
42	  /** How each shown value was confirmed, keyed by field. */
43	  basis: Record<string, string>;
44	}
45	
46	export interface AnswerResult {
47	  question: string;
48	  parsed: ParsedQuery;
49	  answered: boolean;
50	  declineReason: string | null;
51	  /** True when the answer is missing because a provider failed, not because the evidence was thin. */
52	  serviceError: boolean;
53	  claims: CheckedClaim[];
54	  droppedClaims: CheckedClaim[];
55	  firms: FirmSummary[];
56	  /** Firms matching the structured filters, which may exceed those shown. */
57	  totalMatching: number;
58	  timings: { totalMs: number; retrievalMs: number; generationMs: number; auditMs: number };
59	}
60	
61	/**
62	 * Cosine distance above this means the best match is not about the question.
63	 * Tuned on the adversarial query set - see docs/RAG_NOTES.md.
64	 */
65	const MAX_DISTANCE = 0.62;
66	
67	/** What to tell the user when the file simply does not carry the field they asked for. */
68	const FIELD_ABSENT: Record<NonNullable<RequestedField>, string> = {
69	  email: 'No verified email address is held for the firms matching that question. Where an address could not be confirmed it is left blank rather than guessed.',
70	  phone: 'No verified phone number is held for the firms matching that question.',
71	  aum: 'Assets under management are not held for any firm in this dataset. No free statutory source publishes it, so the field is blank throughout rather than estimated.',
72	  sectors: 'Investment sectors are not held for any firm in this dataset. The field is blank throughout rather than inferred.',
73	  thesis: 'Investment thesis is not held for any firm in this dataset.',
74	  website: 'No confirmed website is held for the firms matching that question.',
75	  ranking: 'This dataset holds no size or performance measure, so firms cannot be ranked. Ranking them would require a number that does not exist in any record.',
76	};
77	
78	/**
79	 * True when the firms the question is actually about carry the requested field.
80	 *
81	 * Scoping to the named firm matters. Asked for Francis Family Office's email, an
82	 * unscoped check asks "does any retrieved firm have an email" - and once a few
83	 * records did, the gate opened and the answer listed three other firms' emails.
84	 * Every claim was true and none of them answered the question.
85	 */
86	async function fieldIsHeld(
87	  field: NonNullable<RequestedField>,
88	  firmIds: string[],
89	  question: string,
90	): Promise<boolean> {
91	  if (field === 'ranking' || field === 'aum' || field === 'sectors' || field === 'thesis') return false;
92	  if (firmIds.length === 0) return false;
93	
94	  // If the question names a firm we hold, that firm alone decides the answer -
95	  // whether or not similarity search happened to retrieve it.
96	  const named = await firmsNamedIn(question).catch(() => []);
97	  const scope = named.length > 0 ? named : await getFirms(firmIds);
98	
99	  return scope.some((row) => {
100	    const r = row.record;
101	    const p = r.principals?.[0];
102	    if (field === 'email') return Boolean(p?.email?.value);
103	    if (field === 'phone') return Boolean(p?.phone?.value);
104	    if (field === 'website') return Boolean(r.website?.value);
105	    return false;
106	  });
107	}
108	
109	const ANSWER_SCHEMA = {
110	  type: 'object',
111	  properties: {
112	    claims: {
113	      type: 'array',
114	      items: {
115	        type: 'object',
116	        properties: {
117	          text: { type: 'string' },
118	          cited_chunk_ids: { type: 'array', items: { type: 'string' } },
119	        },
120	        required: ['text', 'cited_chunk_ids'],
121	      },
122	    },
123	  },
124	  required: ['claims'],
125	};
126	
127	/**
128	 * Sources sent to the answering model. Deliberately fewer and shorter than what
129	 * retrieval returns: a 14-chunk prompt costs about 3,900 tokens, which exceeds
130	 * the smaller model's 6,000-per-minute budget once the schema and question are
131	 * added, so every fallback failed too and the user saw "not enough records" when
132	 * the truth was "prompt too large".
133	 */
134	const MAX_SOURCES_IN_PROMPT = 14;
135	/**
136	 * Trimmed from 320. Showing more firms per answer meant more sources per prompt,
137	 * which pushed the fallback model back toward its per-minute ceiling - and a
138	 * model at its ceiling returns an empty claims array rather than an error, which
139	 * surfaces to the user as "not enough records" when the records were fine.
140	 * Fourteen shorter sources cost less than eight long ones.
141	 */
142	const MAX_SOURCE_CHARS = 210;
143	
144	function answerPrompt(question: string, chunks: RetrievedChunk[]): string {
145	  const sources = chunks
146	    .slice(0, MAX_SOURCES_IN_PROMPT)
147	    .map((c) => `[${c.id}] ${c.legal_name} (${c.firm_type})\n    ${c.content.slice(0, MAX_SOURCE_CHARS)}`)
148	    .join('\n');
149	
150	  return `Answer a question from an investor relations professional using ONLY the sources below.
151	
152	QUESTION: ${question}
153	
154	SOURCES:
155	${sources}
156	
157	Write your answer as a list of separate factual claims. For each claim, cite the ids of the sources it rests on.
158	
159	Rules:
160	- Every claim must be supported by the sources you cite for it. An unsupported claim will be removed before the user sees it, so writing one only makes your answer shorter.
161	- One fact per claim. Do not combine several facts into one sentence.
162	- Never state a number, date, or name that does not appear in your cited sources.
163	- Do not rank, compare, or infer causes unless a source states it.
164	- Do not describe the database, your process, or what you were asked. Only state facts about the firms.
165	- If the sources do not answer the question, return an empty claims array. That is a correct response.
166	
167	Write for someone deciding whom to contact. Plain sentences, no marketing language.`;
168	}
169	
170	export async function answerQuestion(question: string): Promise<AnswerResult> {
171	  const t0 = Date.now();
172	  const parsed = await parseQuery(question);
173	
174	  const filters = {
175	    firmType: parsed.firmType ?? undefined,
176	    country: parsed.country ?? undefined,
177	    requireContact: parsed.requireContact,
178	    sinceDate: parsed.sinceDate ?? undefined,
179	  };
180	
181	  const tRetrieve = Date.now();
182	  const [vector, totalMatching] = await Promise.all([
183	    embed(parsed.semanticQuery),
184	    countMatching(filters).catch(() => 0),
185	  ]);
186	  const chunks = await retrieve(
187	    vector,
188	    {
189	      ...filters,
190	      // Whether a firm is reachable is a property of its profile, not of its
191	      // filing history. Asked "who can I phone", unrestricted retrieval fills the
192	      // context with signal chunks about quarterly holdings, and the model then
193	      // correctly concludes the sources do not answer the question.
194	      kinds: parsed.requireContact ? ['profile'] : undefined,
195	    },
196	    30,
197	  );
198	  const retrievalMs = Date.now() - tRetrieve;
199	
200	  const decline = async (reason: string, serviceError = false): Promise<AnswerResult> => {
201	    const result: AnswerResult = {
202	      question,
203	      parsed,
204	      answered: false,
205	      declineReason: reason,
206	      serviceError,
207	      claims: [],
208	      droppedClaims: [],
209	      firms: [],
210	      totalMatching,
211	      timings: { totalMs: Date.now() - t0, retrievalMs, generationMs: 0, auditMs: 0 },
212	    };
213	    await logQuery({
214	      question,
215	      retrievedIds: chunks.map((c) => c.firm_id),
216	      claimsMade: 0,
217	      claimsDropped: 0,
218	      declined: true,
219	      declineReason: reason,
220	      latencyMs: result.timings.totalMs,
221	    }).catch(() => {});
222	    return result;
223	  };
224	
225	  if (chunks.length === 0) {
226	    return decline(
227	      parsed.appliedFilters.length
228	        ? `No firms in the dataset match those criteria (${parsed.appliedFilters.join(', ')}).`
229	        : 'No firms in the dataset relate to that question.',
230	    );
231	  }
232	
233	  const nearest = Math.min(...chunks.map((c) => Number(c.distance)));
234	  if (nearest > MAX_DISTANCE) {
235	    return decline('Nothing in the dataset is close enough to that question to answer it reliably.');
236	  }
237	
238	  const usable = chunks.filter((c) => Number(c.distance) <= MAX_DISTANCE + 0.12);
239	
240	  // If the question asks for a specific field, check we actually hold it before
241	  // generating. Without this the model answers a question about sectors with
242	  // true statements about location - every claim supported, none responsive - and
243	  // the attribution audit passes them all, because grounding is not relevance.
244	  if (parsed.requestedField) {
245	    const held = await fieldIsHeld(parsed.requestedField, [...new Set(usable.map((c) => c.firm_id))], question);
246	    if (!held) {
247	      return decline(FIELD_ABSENT[parsed.requestedField]);
248	    }
249	  }
250	
251	  const tGen = Date.now();
252	  let drafted: { claims: Array<{ text: string; cited_chunk_ids: string[] }> };
253	  try {
254	    drafted = await generateJson(answerPrompt(question, usable), ANSWER_SCHEMA);
255	  } catch (err) {
256	    console.error('answer generation failed:', err instanceof Error ? err.message : err);
257	    const unavailable = err instanceof ServiceUnavailable;
258	    return decline(
259	      unavailable
260	        ? 'The answering service is busy right now. This is not a statement about the records - please try again in a moment.'
261	        : 'Something went wrong composing the answer. The underlying records are unaffected.',
262	      true,
263	    );
264	  }
265	  const generationMs = Date.now() - tGen;
266	
267	  const claims: Claim[] = (drafted.claims ?? []).map((c) => ({
268	    text: c.text,
269	    citedChunkIds: c.cited_chunk_ids ?? [],
270	  }));
271	
272	  if (claims.length === 0) {
273	    console.error(
274	      `no claims drafted: ${usable.length} usable chunks, nearest distance ${nearest.toFixed(3)}, question "${question}"`,
275	    );
276	    return decline('The records retrieved do not contain enough to answer that question.');
277	  }
278	
279	  const tAudit = Date.now();
280	  const { kept, dropped } = await checkAttribution(
281	    claims,
282	    usable.map((c) => ({ id: c.id, content: c.content, firmName: c.legal_name })),
283	  );
284	  const auditMs = Date.now() - tAudit;
285	
286	  if (kept.length === 0) {
287	    const result = await decline(
288	      'An answer was drafted but none of it held up against the underlying records, so it was withheld.',
289	    );
290	    return { ...result, droppedClaims: dropped, timings: { ...result.timings, generationMs, auditMs } };
291	  }
292	
293	  // Only firms actually cited by a surviving claim are shown. Retrieval reaching a
294	  // firm is not a reason to present it.
295	  const citedChunkIds = new Set(kept.flatMap((c) => c.citedChunkIds));
296	  const citedFirmIds = [...new Set(usable.filter((c) => citedChunkIds.has(c.id)).map((c) => c.firm_id))];
297	  const rows = await getFirms(citedFirmIds);
298	
299	  const firms: FirmSummary[] = rows.map((row) => {
300	    const r = row.record;
301	    const p = r.principals?.[0];
302	    const s = r.signals?.[0];
303	    const basis: Record<string, string> = {};
304	    const note = (label: string, cell?: { evidence?: Array<{ method: string; sourceUrl: string; vendor?: string }> }) => {
305	      const e = cell?.evidence?.[0];
306	      if (e) basis[label] = `${e.method}${e.vendor ? ` [via ${e.vendor}]` : ''}`;
307	    };
308	    note('type', { evidence: r.classification?.evidence });
309	    note('phone', p?.phone);
310	    note('email', p?.email);
311	    note('website', r.website);
