/**
 * Run-lifecycle consistency rules.
 *
 * The operating-window log is the product's evidence surface: a buyer is invited
 * to inspect what ran, when, what it caught and what broke. So a run row is held
 * to the same standard as a claim -- a value it never observed must not be
 * recorded as if it had been.
 *
 * ### What went wrong
 *
 * `finish()` is the only code path that ends a run, and it writes the end time
 * and the four counters in one statement. A process killed by SIGKILL never
 * reaches it, so its row stays in `running` with the counters at their schema
 * default of 0.
 *
 * Those orphaned rows were later closed by hand:
 *
 *   UPDATE s2_run SET status='aborted', ended_at=now() WHERE status='running'
 *
 * That statement is in the submitted session record, twice without a reason and
 * once with one. It writes an end time and leaves the counters alone, so each
 * swept row ends up asserting two things the system never observed: that the run
 * stopped at the moment of the cleanup, and that it did no work.
 *
 * Both are false and both are checkable. In `exports/operating-window.json`, one
 * `contract` run records a 74-hour duration against a 40-minute maximum across
 * 108 real completions, and a `discover` run reports `claimsQuarantined: 0`
 * while carrying a quarantine decision in the same object.
 *
 * ### Why these rules, and not a timestamp heuristic
 *
 * The first draft flagged runs sharing an `ended_at` to the millisecond. That
 * detects this particular incident and nothing else: it false-positives on
 * genuinely concurrent runs, and a cleanup that closed rows one at a time would
 * pass it untouched. It tests the symptom.
 *
 * These rules test the lifecycle instead. An end time is only meaningful if it
 * came from the write that ended the run, and that write also records the
 * counters -- so an end time standing beside unwritten counters did not come
 * from the run finishing, whatever its value. That is exact. No tolerance, no
 * threshold, and it holds however the orphan was closed.
 *
 * Pure functions over plain rows on purpose: the same rules run against the
 * database in the `contract` job and against an exported file, so a reviewer can
 * check the artifact without credentials.
 */

/** Terminal states. A run in one of these is making a claim about how it ended. */
const TERMINAL = new Set(['completed', 'failed', 'halted_budget', 'aborted']);

export interface RunCounts {
  recordsTouched: number | null;
  claimsCreated: number | null;
  claimsReleased: number | null;
  claimsQuarantined: number | null;
}

/**
 * A run as either surface presents it.
 *
 * `closedAt`/`closeReason` are optional because rows written before the fix do
 * not carry them -- their absence on an orphaned run is itself a violation.
 */
export interface RunRecord {
  runId: string;
  job: string;
  trigger: string;
  status: string;
  startedAt: string;
  endedAt: string | null;
  closedAt?: string | null;
  closeReason?: string | null;
  counts: RunCounts;
  log: Array<{ at: string; level?: string; event: string }>;
  decisions: Array<{ kind: string }>;
}

export type LifecycleRule =
  | 'end_time_without_completion'
  | 'orphan_closed_without_reason'
  | 'end_time_and_close_time'
  | 'counts_contradict_decisions'
  | 'no_work_recorded_despite_activity';

export interface LifecycleViolation {
  runId: string;
  rule: LifecycleRule;
  detail: string;
}

/** Counters are "unwritten" when every one is absent, or all still at the default. */
function countersUnwritten(c: RunCounts): boolean {
  const vals = [c.recordsTouched, c.claimsCreated, c.claimsReleased, c.claimsQuarantined];
  if (vals.every((v) => v === null || v === undefined)) return true;
  return vals.every((v) => v === 0);
}

/** Did this run actually do anything? Decisions and per-entity log events both count. */
function activitySeen(r: RunRecord): number {
  const decisions = r.decisions?.length ?? 0;
  const working = (r.log ?? []).filter(
    (l) => l.event !== 'run_started' && l.event !== 'run_failed',
  ).length;
  return decisions + working;
}

function quarantineDecisions(r: RunRecord): number {
  return (r.decisions ?? []).filter((d) => d.kind === 'quarantine').length;
}

/**
 * Check one run against every rule. Returns every violation, not the first --
 * a row can be wrong in more than one way, and fixing one at a time is how the
 * second defect gets missed.
 */
export function checkRun(r: RunRecord): LifecycleViolation[] {
  const out: LifecycleViolation[] = [];
  const v = (rule: LifecycleRule, detail: string) => out.push({ runId: r.runId, rule, detail });

  const unwritten = countersUnwritten(r.counts);
  const activity = activitySeen(r);

  // The core rule. `finish()` writes the end time and the counters together, so
  // an end time beside unwritten counters was written by something else -- and
  // whatever that was, it did not observe the run stopping.
  if (r.endedAt && unwritten && activity > 0) {
    v(
      'end_time_without_completion',
      `endedAt=${r.endedAt} is set while the counters are unwritten, on a run with ` +
        `${activity} recorded actions. The completion path writes both; this end time did not come from it.`,
    );
  }

  // An orphan is allowed. An orphan that does not say it is one is not.
  if (TERMINAL.has(r.status) && unwritten && activity > 0 && !r.closeReason) {
    v(
      'orphan_closed_without_reason',
      `status=${r.status} with no completion behind it and no closeReason. ` +
        'A run closed administratively must record that it was, and why.',
    );
  }

  // The two timestamps mean different things and must never both be asserted:
  // one says when the run stopped, the other when we gave up waiting.
  if (r.endedAt && r.closedAt) {
    v(
      'end_time_and_close_time',
      `both endedAt=${r.endedAt} and closedAt=${r.closedAt} are set. ` +
        'An observed end and an administrative closure are mutually exclusive.',
    );
  }

  // A counter is a measurement. It may be absent; it may not disagree with the
  // run's own decision log.
  const quarantined = quarantineDecisions(r);
  if (r.counts.claimsQuarantined !== null && r.counts.claimsQuarantined < quarantined) {
    v(
      'counts_contradict_decisions',
      `claimsQuarantined=${r.counts.claimsQuarantined} but the run holds ${quarantined} ` +
        'quarantine decision(s) in the same record.',
    );
  }

  // "Touched nothing" is a strong claim, and the log is standing right next to it.
  if (r.counts.recordsTouched === 0 && activity > 0) {
    v(
      'no_work_recorded_despite_activity',
      `recordsTouched=0 while the run holds ${activity} recorded actions ` +
        `(${r.decisions?.length ?? 0} decisions, ${r.log?.length ?? 0} log lines). ` +
        'Unknown is not zero.',
    );
  }

  return out;
}

export function checkRuns(runs: RunRecord[]): LifecycleViolation[] {
  return runs.flatMap(checkRun);
}

/** Grouped for a human: which rules fired, and how often. */
export function summarise(violations: LifecycleViolation[]): Record<LifecycleRule, number> {
  const out = {} as Record<LifecycleRule, number>;
  for (const x of violations) out[x.rule] = (out[x.rule] ?? 0) + 1;
  return out;
}

