import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { checkRun, checkRuns, summarise, type RunRecord } from './run-lifecycle.js';

/**
 * These rules are proved against the submitted artifact, not a fixture.
 *
 * A check written after the fact can always be made to pass. The test that means
 * something is the one that runs the new rules over `exports/operating-window.json`
 * exactly as it was submitted and shows them firing on the real rows -- and,
 * just as importantly, staying silent on all 108 runs that completed normally.
 * A rule that flags healthy runs would be worse than the defect it catches.
 *
 * The export is read read-only and never rewritten. It is submitted evidence.
 */

const EXPORT = fileURLToPath(new URL('../../../../exports/operating-window.json', import.meta.url));

function loadSubmittedRuns(): RunRecord[] {
  const raw = JSON.parse(readFileSync(EXPORT, 'utf8')) as { runs: any[] };
  return raw.runs.map((r) => ({
    runId: r.runId,
    job: r.job,
    trigger: r.trigger,
    status: r.status,
    startedAt: r.startedAt,
    endedAt: r.endedAt ?? null,
    closedAt: r.closedAt ?? null,
    closeReason: r.closeReason ?? null,
    counts: {
      recordsTouched: r.counts?.recordsTouched ?? null,
      claimsCreated: r.counts?.claimsCreated ?? null,
      claimsReleased: r.counts?.claimsReleased ?? null,
      claimsQuarantined: r.counts?.claimsQuarantined ?? null,
    },
    log: r.log ?? [],
    decisions: r.decisions ?? [],
  }));
}

test('lifecycle · the submitted export violates the rules, on the aborted rows only', () => {
  const runs = loadSubmittedRuns();
  const violations = checkRuns(runs);
  const offenders = new Set(violations.map((v) => v.runId));

  // Every run that violates anything is one of the seven that never completed.
  for (const id of offenders) {
    const run = runs.find((r) => r.runId === id)!;
    assert.equal(run.status, 'aborted', `${id} is ${run.status}, expected only aborted rows to fail`);
  }

  assert.equal(offenders.size, 7, 'all seven administratively-closed runs should be caught');
  assert.ok(violations.length > 0);
});

test('lifecycle · the 108 completed runs raise nothing', () => {
  const completed = loadSubmittedRuns().filter((r) => r.status === 'completed');
  assert.ok(completed.length >= 100, 'sanity: the export should hold ~109 completed runs');
  assert.deepEqual(checkRuns(completed), [], 'a healthy run must never trip these rules');
});

test('lifecycle · every rule fires on the submitted data', () => {
  const counts = summarise(checkRuns(loadSubmittedRuns()));
  // A rule that never fires on the artifact it was written for is decoration.
  assert.ok(counts.end_time_without_completion > 0);
  assert.ok(counts.orphan_closed_without_reason > 0);
  assert.ok(counts.no_work_recorded_despite_activity > 0);
  assert.ok(counts.counts_contradict_decisions > 0, 'the quarantine contradiction must be caught');
});

test('lifecycle · THE PRODUCTION ROW: a quarantine reported as zero is caught', () => {
  const run = loadSubmittedRuns().find((r) => r.runId === 'run_20260730191237_40bd4888')!;
  const rules = checkRun(run).map((v) => v.rule);
  assert.ok(rules.includes('counts_contradict_decisions'));
  assert.ok(rules.includes('end_time_without_completion'));
});

