  const counts = summarise(checkRuns(loadSubmittedRuns()));
  // A rule that never fires on the artifact it was written for is decoration.
  assert.ok(counts.end_time_without_completion > 0);
  assert.ok(counts.orphan_closed_without_reason > 0);
  assert.ok(counts.no_work_recorded_despite_activity > 0);
  assert.ok(counts.counts_contradict_decisions > 0, 'the quarantine contradiction must be caught');
