        `${minutes} minute(s) when the row was closed. The end time is unknown and is not recorded.`;

    out.push({ runId: r.runId, job: r.job, silentMs, reason });
  }

  return out;
}

export interface CloseResult {
  scanned: number;
  closed: OrphanDecision[];
  /** running rows deliberately left alone, because they are still speaking */
  leftRunning: number;
  dryRun: boolean;
}

/**
 * Find every orphaned run and close it properly.
 *
 * Safe to run repeatedly: a row it closes is no longer `running`, so a second
 * invocation finds nothing. Safe to run while other jobs are working, because
 * only silence past the threshold qualifies.
 */
export async function closeOrphanedRuns(opts: {
  silenceMs?: number;
  excludeRunId?: string;
  dryRun?: boolean;
  now?: Date;
} = {}): Promise<CloseResult> {
  const sql = connect();
  const now = opts.now ?? new Date();
  const dryRun = opts.dryRun ?? false;

  const rows = (await withRetry(
    () => sql`
      SELECT r.id, r.job, r.trigger, r.started_at,
             (SELECT max(l.at) FROM s2_run_log l WHERE l.run_id = r.id) AS last_activity_at
      FROM s2_run r
      WHERE r.status = 'running'
      ORDER BY r.started_at ASC`,
    3,
    'select orphaned runs',
  )) as unknown as Array<Record<string, any>>;

  const candidates: OrphanCandidate[] = rows.map((r) => ({
    runId: r.id,
    job: r.job,
    trigger: r.trigger,
    startedAt: new Date(r.started_at).toISOString(),
    lastActivityAt: r.last_activity_at ? new Date(r.last_activity_at).toISOString() : null,
  }));

  const closed = selectOrphans(candidates, { now, silenceMs: opts.silenceMs, excludeRunId: opts.excludeRunId });

  if (!dryRun) {
    for (const d of closed) {
      // The log line goes on the orphan's own run, so the closure appears in the
      // same stream as everything else that run did rather than in a side
      // channel a reader has to know about. Written before the update: if the
      // update then fails, the row stays `running` and is swept next time, which
      // is recoverable. A row closed with no trace of why would not be.
      await withRetry(
        () => sql`
          INSERT INTO s2_run_log (run_id, level, event, detail)
          VALUES (${d.runId}, 'warn', 'run_closed_administratively',
                  ${JSON.stringify({ silentMs: d.silentMs, closedAt: now.toISOString(), reason: d.reason })}::jsonb)`,
        3,
        'log administrative closure',
      );

      // Note what is absent: `ended_at` is not set, and the counters are not
      // touched. This statement records only what is known -- that the row was
      // closed, when, and why.
      await withRetry(
        () => sql`
          UPDATE s2_run
             SET status = 'aborted', closed_at = ${now.toISOString()}, close_reason = ${d.reason}
           WHERE id = ${d.runId} AND status = 'running'`,
        3,
        'close orphaned run',
      );
    }
  }

  return { scanned: candidates.length, closed, leftRunning: candidates.length - closed.length, dryRun };
}

