70	/**
71	 * A store that mimics the UPDATE's own WHERE clause.
72	 *
73	 * `aliveAgain` is the set of runs that logged something after selection. The
74	 * real statement rechecks silence in SQL and returns no rows for those; this
75	 * does the same thing in memory, and records every call so a test can prove the
76	 * log was never written for a row that did not close.
77	 */
78	function fakeStore(aliveAgain: Set<string> = new Set()) {
79	  const closedRows: string[] = [];
80	  const logged: string[] = [];
81	  const store: ClosureStore = {
82	    async tryClose(runId) {
83	      if (aliveAgain.has(runId)) return false; // the recheck fails: it is alive
84	      closedRows.push(runId);
85	      return true;
86	    },
87	    async recordClosure(runId) {
88	      logged.push(runId);
89	    },
90	  };
91	  return { store, closedRows, logged };
92	}
93	
94	const decision = (runId: string): OrphanDecision => ({
95	  runId, job: 'discover', silentMs: 90 * 60_000, reason: 'no completion record; silent for 90 minute(s)',
96	});
97	
98	const APPLY = { closedAt: NOW.toISOString(), silentSince: agoMin(30) };
99	
100	test('close · THE RACE: a run that logs again before the update is left untouched', () => {
101	  const { store, closedRows, logged } = fakeStore(new Set(['run_revived']));
102	  return applyClosures(store, [decision('run_revived')], APPLY).then((r) => {
103	    // Nothing updated, nothing logged, and it is reported as skipped rather than
104	    // closed. The previous ordering wrote the closure log line first, which left
105	    // a `run_closed_administratively` entry describing a closure that never
106	    // happened -- a false statement written by the fix for false statements.
107	    assert.deepEqual(closedRows, [], 'the run must not be closed');
108	    assert.deepEqual(logged, [], 'and no closure may be logged for it');
109	    assert.deepEqual(r.closed, []);
110	    assert.deepEqual(r.skippedByRecheck, ['run_revived']);
111	  });
112	});
