115	  const { store, closedRows, logged } = fakeStore(new Set(['run_revived']));
116	  return applyClosures(store, [decision('run_revived'), decision('run_dead')], APPLY).then((r) => {
117	    assert.deepEqual(closedRows, ['run_dead']);
118	    assert.deepEqual(logged, ['run_dead']);
119	    assert.deepEqual(r.closed.map((c) => c.runId), ['run_dead']);
120	    assert.deepEqual(r.skippedByRecheck, ['run_revived']);
121	  });
122	});
123	
124	test('close · the closure log is written only for a row that actually closed', () => {
125	  const { store, closedRows, logged } = fakeStore();
126	  return applyClosures(store, [decision('run_a'), decision('run_b')], APPLY).then(() => {
127	    // One log line per closed row, never more, never for a row that did not close.
128	    assert.deepEqual(logged, closedRows);
129	  });
130	});
