132	test('close · reported results count updates, not intentions', () => {
133	  const { store } = fakeStore(new Set(['run_x', 'run_y']));
134	  return applyClosures(store, [decision('run_x'), decision('run_y'), decision('run_z')], APPLY).then((r) => {
135	    assert.equal(r.closed.length, 1, 'three selected, one actually updated');
136	    assert.equal(r.skippedByRecheck.length, 2);
137	  });
138	});
