154	    startedAt: agoMin(120),
155	    endedAt: null,                        // never written — nothing observed it
156	    closedAt: NOW.toISOString(),          // a fact: when the row was closed
157	    closeReason: d!.reason,
158	    counts: { recordsTouched: null, claimsCreated: null, claimsReleased: null, claimsQuarantined: null },
159	    failures: [],
160	    log: [{ at: agoMin(90), event: 'contacts_synced' }],
161	    decisions: [{ kind: 'classify' }],
162	  };
163	
164	  assert.deepEqual(checkRun(written), [], 'the closure this function writes must be clean');
165	  assert.deepEqual(errors(checkRun(written)), []);
166	});
