46	export async function startRun(job: RunJob, trigger: RunTrigger = 'manual'): Promise<RunHandle> {
47	  const id = `run_${new Date().toISOString().slice(0, 19).replace(/[:T-]/g, '')}_${randomUUID().slice(0, 8)}`;
48	  const policyVersion = (await import('../release/gate.js')).POLICY_VERSION;
49	
50	  await withRetry(() => sql`
51	    INSERT INTO s2_run (id, trigger, job, status, git_sha, policy_version)
52	    VALUES (${id}, ${trigger}, ${job}, 'running', ${gitSha()}, ${policyVersion})`, 4, 'startRun');
53	
54	  const counts = { created: 0, released: 0, quarantined: 0, touched: 0 };
55	  const failures: unknown[] = [];
56	
57	  const handle: RunHandle = {
58	    id,
59	    job,
60	    counts,
61	    failures,
62	
63	    async log(level, event, detail) {
64	      // stdout first: if the database write is what is failing, the Actions log
65	      // is the only place the reason can still appear.
66	      const line = { run: id, job, level, event, ...(detail ? { detail } : {}) };
67	      console.log(JSON.stringify(line));
68	      try {
69	        await withRetry(() => sql`
70	          INSERT INTO s2_run_log (run_id, level, event, detail)
71	          VALUES (${id}, ${level}, ${event}, ${detail ? JSON.stringify(detail) : null}::jsonb)`, 2, 'log');
72	      } catch (err) {
73	        console.log(JSON.stringify({ run: id, level: 'warn', event: 'log_write_failed', detail: String(err) }));
74	      }
75	    },
76	
77	    async decision(kind, o) {
78	      await withRetry(() => sql`
79	        INSERT INTO s2_decision_log (id, run_id, entity_id, claim_id, kind, rule, before_json, after_json, reason)
80	        VALUES (${`dl_${randomUUID()}`}, ${id}, ${o.entityId ?? null}, ${o.claimId ?? null}, ${kind}, ${o.rule},
81	                ${o.before ? JSON.stringify(o.before) : null}::jsonb,
82	                ${o.after ? JSON.stringify(o.after) : null}::jsonb, ${o.reason})`, 3, 'decision');
83	    },
84	
85	    /**
86	     * Called only after the unit's writes have committed. A cursor written
87	     * before the write would make the next run skip a unit that was never
88	     * stored -- data loss that looks exactly like normal progress.
89	     */
90	    async checkpoint(sourceId, cursor, unitsDone) {
91	      await withRetry(() => sql`
92	        INSERT INTO s2_checkpoint (id, job, source_id, cursor, units_done, last_run_id)
93	        VALUES (${`cp_${job}_${sourceId}`}, ${job}, ${sourceId}, ${cursor}, ${unitsDone}, ${id})
94	        ON CONFLICT (job, source_id) DO UPDATE SET
95	          cursor = EXCLUDED.cursor, units_done = EXCLUDED.units_done,
96	          last_run_id = EXCLUDED.last_run_id, updated_at = now()`, 3, 'checkpoint');
97	    },
98	
