100	      const rows = (await withRetry(() => sql`
101	        SELECT cursor FROM s2_checkpoint WHERE job = ${job} AND source_id = ${sourceId}`,
102	        3, 'readCheckpoint')) as unknown as Array<{ cursor: string | null }>;
103	      return rows[0]?.cursor ?? null;
104	    },
105	
106	    async finish(status, cost) {
107	      await withRetry(() => sql`
108	        UPDATE s2_run SET status = ${status}, ended_at = now(),
109	          records_touched = ${counts.touched}, claims_created = ${counts.created},
110	          claims_released = ${counts.released}, claims_quarantined = ${counts.quarantined},
111	          failures_json = ${JSON.stringify(failures)}::jsonb,
112	          cost_json = ${JSON.stringify(cost ?? {})}::jsonb
113	        WHERE id = ${id}`, 4, 'finish');
114	      console.log(JSON.stringify({ run: id, job, event: 'run_finished', status, counts, failures: failures.length }));
115	    },
116	  };
117	
118	  await handle.log('info', 'run_started', { trigger, gitSha: gitSha() });
119	  return handle;
120	}
