122	/**
123	 * Wraps a whole job so a crash still closes its run row.
124	 *
125	 * A run left in `running` forever is worse than a run marked failed: the
126	 * operating evidence has to distinguish "this broke" from "this is still going",
127	 * and an abandoned row makes every later query ambiguous.
128	 */
129	export async function withRun(
130	  job: RunJob,
131	  trigger: RunTrigger,
132	  fn: (run: RunHandle) => Promise<void>,
133	): Promise<RunHandle> {
134	  // Cleared at the start rather than the end, so a previous run that died
135	  // without finishing cannot bleed its spend into this one's figures.
136	  resetMeter();
137	  const startedAt = Date.now();
138	  const run = await startRun(job, trigger);
139	
140	  // A failed run's cost is the interesting one -- it is what a retry will cost
141	  // again -- so the snapshot is taken on both paths.
142	  const cost = () => ({ ...meterSnapshot(), wallMs: Date.now() - startedAt });
143	
144	  try {
145	    await fn(run);
146	    await run.finish('completed', cost());
147	  } catch (err) {
148	    run.failures.push({ fatal: true, message: err instanceof Error ? err.message : String(err) });
149	    await run.log('error', 'run_failed', { message: err instanceof Error ? err.message : String(err) });
150	    await run.finish('failed', cost());
151	    throw err;
152	  }
153	  return run;
154	}
