toolUseResult.originalFile:
/**
 * When to persist a run's counters, and why they are persisted at all.
 *
 * The counters used to be written once, by `finish()`, in the same statement as
 * the end time. A process killed by SIGKILL never reaches it, so the row kept
 * the schema default of 0 -- and after the hand-written cleanup gave that row a
 * status and an end time, it read as a run that completed and did nothing.
 *
 * `run_20260730191237_40bd4888` is the case worth remembering: 43 log lines, 42
 * decisions including a quarantine, and `claimsQuarantined: 0` on the row above
 * them. The work happened; the record of it did not survive.
 *
 * The log lines survived because they are written as they occur. So the fix for
 * the counters is the same shape: write them as the work commits, and let
 * whatever was committed before the kill be what the row reports. A killed run
 * then shows a true partial count instead of reverting to zero.
 *
 * ### Why a policy module rather than a line in `runner.ts`
 *
 * Persisting on every increment would issue a write per record, which at 581
 * records is thousands of statements to save a number nobody reads until
 * something goes wrong. Persisting rarely loses the work the fix exists to
 * preserve. The compromise is a throttle, and a throttle is a decision with
 * edge cases -- so it lives here, pure and tested, rather than inline in a
 * module that cannot be imported without a database connection.
 */

export interface RunCounts {
  created: number;
  released: number;
  quarantined: number;
  touched: number;
}

export interface FlushState {
  /** epoch ms of the last successful write; 0 means never */
  lastFlushAt: number;
  /** the counters as they stood at that write, or null */
  lastFlushed: string | null;
}

/**
 * How long to wait between writes while a job is working.
 *
 * Five seconds against runs whose median length is well under a minute means a
 * handful of extra statements per run, and bounds what a kill can destroy to
 * five seconds of counting. The exact value matters less than the two
 * properties either side of it: a commit boundary always flushes regardless, and
 * an unchanged counter never writes at all.
 */
export const DEFAULT_FLUSH_INTERVAL_MS = 5_000;

export function newFlushState(): FlushState {
  // Zero rather than `Date.now()`, so the first real change is written
  // immediately instead of waiting out an interval. A run that dies in its first
  // seconds is exactly the case where the partial count is most informative.
  return { lastFlushAt: 0, lastFlushed: null };
}

function snapshot(c: RunCounts): string {
  return `${c.touched}/${c.created}/${c.released}/${c.quarantined}`;
}

/**
 * Should the counters be written now?
 *
 * `force` is for commit boundaries -- the checkpoint, and the end of the run --
 * where the point is that what is on disk matches what was committed, not that
 * enough time has passed.
 *
 * Unchanged counters are never written, forced or not. A write that stores the
 * same four numbers again is noise in the row's update history and buys nothing;
 * the caller that wants an unconditional write is `finish()`, which is writing
 * the status and the end time anyway and does not come through here.
 */
export function shouldFlush(
  state: FlushState,
  counts: RunCounts,
  now: number,
  opts: { force?: boolean; intervalMs?: number } = {},
): boolean {
  const sig = snapshot(counts);
  if (state.lastFlushed === sig) return false;
  if (opts.force) return true;
  return now - state.lastFlushAt >= (opts.intervalMs ?? DEFAULT_FLUSH_INTERVAL_MS);
}

/** Record that a write succeeded. Only called after the statement commits. */
export function markFlushed(state: FlushState, counts: RunCounts, now: number): void {
  state.lastFlushAt = now;
  state.lastFlushed = snapshot(counts);
}

import { meterSnapshot, resetMeter } from '@fo/core';
import { randomUUID } from 'node:crypto';
import { execSync } from 'node:child_process';
import { connect, withRetry } from '../../../db/src/connect.js';
import { newFlushState, shouldFlush, markFlushed } from './count-flush.js';
import type { DecisionKind, RunJob, RunStatus, RunTrigger } from '@fo/core/contract/index.js';

/**
 * The operating record.
 *
 * Every scheduled execution opens a run, writes what it did as it goes, and
 * closes it. The brief asks for complete logs across a 48-hour unattended
 * window plus evidence of a real dependency failure and a real staleness event
 * -- those are claims about behaviour, and they are only credible if the rows
 * were written while the behaviour happened rather than composed afterwards.
 *
 * Logs go to two places on purpose. GitHub Actions logs are the operator's view
 * and expire; Neon rows are queryable and outlive the workflow retention.
 */

const sql = connect();

function gitSha(): string | null {
  if (process.env.GITHUB_SHA) return process.env.GITHUB_SHA.slice(0, 12);
  try {
    return execSync('git rev-parse --short HEAD', { encoding: 'utf8' }).trim();
  } catch {
    return null;
  }
}

export interface RunHandle {
  id: string;
  job: RunJob;
  log(level: 'debug' | 'info' | 'warn' | 'error', event: string, detail?: unknown): Promise<void>;
  decision(kind: DecisionKind, opts: {
    entityId?: string; claimId?: string; rule: string;
    before?: unknown; after?: unknown; reason: string;
  }): Promise<void>;
  checkpoint(sourceId: string, cursor: string, unitsDone: number): Promise<void>;
  readCheckpoint(sourceId: string): Promise<string | null>;
  counts: { created: number; released: number; quarantined: number; touched: number };
  failures: unknown[];
  /**
   * Persist the counters now, whatever the throttle says.
   *
   * Called automatically at every checkpoint and at the end of the run. Exposed
   * so a job can force it at a boundary of its own -- there is no harm in
   * calling it, and it is a no-op when nothing has changed.
   */
  flushCounts(): Promise<void>;
  finish(status: RunStatus, cost?: Record<string, unknown>): Promise<void>;
}

export async function startRun(job: RunJob, trigger: RunTrigger = 'manual'): Promise<RunHandle> {
  const id = `run_${new Date().toISOString().slice(0, 19).replace(/[:T-]/g, '')}_${randomUUID().slice(0, 8)}`;
  const policyVersion = (await import('../release/gate.js')).POLICY_VERSION;

  await withRetry(() => sql`
    INSERT INTO s2_run (id, trigger, job, status, git_sha, policy_version)
    VALUES (${id}, ${trigger}, ${job}, 'running', ${gitSha()}, ${policyVersion})`, 4, 'startRun');

  const counts = { created: 0, released: 0, quarantined: 0, touched: 0 };
  const failures: unknown[] = [];
  const flushState = newFlushState();

  /**
   * Write the counters, and only the counters.
   *
   * Deliberately does not touch `ended_at`, `status`, or anything else: this
   * runs while the job is still working, and a `running` row that carried an end
   * time would violate `s2_run_outcome_times` as well as being false.
   *
   * Never throws. Losing a counter write is a degraded record; failing the whole
   * job because a counter write failed would be a worse outcome than the problem
   * it is guarding against. The failure is logged to stdout, like a failed log
   * write, so it is visible without being fatal.
   */
  const persistCounts = async (force: boolean): Promise<void> => {
    const now = Date.now();
    if (!shouldFlush(flushState, counts, now, { force })) return;
    try {
      await withRetry(() => sql`
        UPDATE s2_run SET
          records_touched = ${counts.touched}, claims_created = ${counts.created},
          claims_released = ${counts.released}, claims_quarantined = ${counts.quarantined}
        WHERE id = ${id}`, 2, 'flushCounts');
      markFlushed(flushState, counts, now);
    } catch (err) {
      console.log(JSON.stringify({ run: id, level: 'warn', event: 'count_flush_failed', detail: String(err) }));
    }
  };

  const handle: RunHandle = {
    id,
    job,
    counts,
    failures,

    async log(level, event, detail) {
      // stdout first: if the database write is what is failing, the Actions log
      // is the only place the reason can still appear.
      const line = { run: id, job, level, event, ...(detail ? { detail } : {}) };
      console.log(JSON.stringify(line));
      try {
        await withRetry(() => sql`
          INSERT INTO s2_run_log (run_id, level, event, detail)
          VALUES (${id}, ${level}, ${event}, ${detail ? JSON.stringify(detail) : null}::jsonb)`, 2, 'log');
      } catch (err) {
        console.log(JSON.stringify({ run: id, level: 'warn', event: 'log_write_failed', detail: String(err) }));
      }
      // Jobs log as they work, so this is the natural heartbeat to hang the
      // throttled counter write on -- no job has to remember to call anything.
      await persistCounts(false);
    },

    async decision(kind, o) {
      await withRetry(() => sql`
        INSERT INTO s2_decision_log (id, run_id, entity_id, claim_id, kind, rule, before_json, after_json, reason)
        VALUES (${`dl_${randomUUID()}`}, ${id}, ${o.entityId ?? null}, ${o.claimId ?? null}, ${kind}, ${o.rule},
                ${o.before ? JSON.stringify(o.before) : null}::jsonb,
                ${o.after ? JSON.stringify(o.after) : null}::jsonb, ${o.reason})`, 3, 'decision');
    },

    /**
     * Called only after the unit's writes have committed. A cursor written
     * before the write would make the next run skip a unit that was never
     * stored -- data loss that looks exactly like normal progress.
     */
    async checkpoint(sourceId, cursor, unitsDone) {
      await withRetry(() => sql`
        INSERT INTO s2_checkpoint (id, job, source_id, cursor, units_done, last_run_id)
        VALUES (${`cp_${job}_${sourceId}`}, ${job}, ${sourceId}, ${cursor}, ${unitsDone}, ${id})
        ON CONFLICT (job, source_id) DO UPDATE SET
          cursor = EXCLUDED.cursor, units_done = EXCLUDED.units_done,
          last_run_id = EXCLUDED.last_run_id, updated_at = now()`, 3, 'checkpoint');
      // A checkpoint means "this unit's writes are committed". That is exactly
      // the moment the counters should match what is on disk, so the throttle is
      // bypassed: if the process dies immediately after, the row and the
      // checkpoint agree about how far the run got.
      await persistCounts(true);
    },

    async readCheckpoint(sourceId) {
      const rows = (await withRetry(() => sql`
        SELECT cursor FROM s2_checkpoint WHERE job = ${job} AND source_id = ${sourceId}`,
        3, 'readCheckpoint')) as unknown as Array<{ cursor: string | null }>;
      return rows[0]?.cursor ?? null;
    },

    async flushCounts() {
      await persistCounts(true);
    },

    async finish(status, cost) {
      await withRetry(() => sql`
        UPDATE s2_run SET status = ${status}, ended_at = now(),
          records_touched = ${counts.touched}, claims_created = ${counts.created},
          claims_released = ${counts.released}, claims_quarantined = ${counts.quarantined},
          failures_json = ${JSON.stringify(failures)}::jsonb,
          cost_json = ${JSON.stringify(cost ?? {})}::jsonb
